"use client";

import { useEffect, useState, use } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  ArrowLeft,
  Save,
  User,
  Bot,
  Activity,
  CreditCard,
  History,
  Shield,
  ExternalLink,
  Plus,
} from "lucide-react";
import { toast } from "sonner";
import { useConfirmation } from "@/components/ui/confirmation-provider";

interface Plan {
  id: string;
  name: string;
  price: number;
}

interface UserData {
  id: string;
  name: string | null;
  email: string | null;
  isAdmin: boolean;
  createdAt: string;
}

interface BotData {
  id: string;
  name: string;
  enabled: boolean;
  channels: Array<{
    id: string;
    type: string;
    isActive: boolean;
  }>;
}

interface FlowData {
  id: string;
  name: string;
  isActive: boolean;
  _count: {
    sessions: number;
    leads: number;
  };
}

interface LogData {
  id: string;
  type: string;
  title: string;
  description: string;
  createdAt: string;
  user?: {
    name: string | null;
    email: string | null;
  };
}

interface ExecutionLogData {
  id: string;
  bot: { name: string };
  user: { name: string | null; email: string | null };
  direction: string;
  status: string;
  errorMessage: string | null;
  createdAt: string;
}

interface SubscriberData {
  id: string;
  status: string;
  currentPeriodEnd: string | null;
  stripeId: string | null;
  plan: Plan;
  tenant: {
    id: string;
    name: string;
    users: UserData[];
    bots: BotData[];
    flows: FlowData[];
    activityLogs: LogData[];
  };
}

export default function SubscriberDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const activeTab = searchParams.get("tab") || "overview";
  const { id } = use(params);
  const { confirm } = useConfirmation();
  const [data, setData] = useState<{
    subscription: SubscriberData;
    executionLogs: ExecutionLogData[];
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [creatingFlow, setCreatingFlow] = useState(false);
  const [plans, setPlans] = useState<Plan[]>([]);

  // Form states
  const [status, setStatus] = useState("");
  const [planId, setPlanId] = useState("");
  const [periodEnd, setPeriodEnd] = useState("");

  useEffect(() => {
    fetchData();
    fetchPlans();
  }, [id]);

  const fetchData = async () => {
    try {
      const response = await fetch(`/api/admin/subscribers/${id}`);
      if (response.ok) {
        const result = await response.json();
        setData(result);
        setStatus(result.subscription.status);
        setPlanId(result.subscription.plan.id);
        setPeriodEnd(
          result.subscription.currentPeriodEnd
            ? new Date(result.subscription.currentPeriodEnd)
              .toISOString()
              .split("T")[0]
            : "",
        );
      } else {
        toast.error("Failed to fetch subscriber data");
      }
    } catch (error) {
      console.error("Error fetching subscriber:", error);
      toast.error("Error loading subscriber");
    } finally {
      setLoading(false);
    }
  };

  const fetchPlans = async () => {
    try {
      const response = await fetch("/api/admin/plans");
      if (response.ok) {
        const result = await response.json();
        setPlans(result.plans);
      }
    } catch (error) {
      console.error("Error fetching plans:", error);
    }
  };

  const handleUpdateSubscription = async () => {
    setSaving(true);
    try {
      const response = await fetch(`/api/admin/subscribers/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          status,
          planId,
          currentPeriodEnd: periodEnd ? new Date(periodEnd).toISOString() : null,
        }),
      });

      if (response.ok) {
        toast.success("Subscription updated successfully");
        fetchData();
      } else {
        toast.error("Failed to update subscription");
      }
    } catch (error) {
      console.error("Error updating subscription:", error);
      toast.error("Error updating subscription");
    } finally {
      setSaving(false);
    }
  };

  const handleToggleUserAdmin = async (userId: string, currentStatus: boolean) => {
    const confirmed = await confirm({
      title: currentStatus ? "Revoke Admin Privileges" : "Grant Admin Privileges",
      description: `Are you sure you want to ${currentStatus ? "revoke" : "grant"
        } admin privileges for this user?`,
      confirmText: currentStatus ? "Revoke" : "Grant",
    });

    if (!confirmed) return;

    try {
      const response = await fetch(`/api/admin/users/${userId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ isAdmin: !currentStatus }),
      });

      if (response.ok) {
        toast.success("User updated successfully");
        fetchData();
      } else {
        const err = await response.json();
        toast.error(err.error || "Failed to update user");
      }
    } catch (error) {
      console.error("Error updating user:", error);
      toast.error("Error updating user");
    }
  };

  const handleCreateFlow = async () => {
    setCreatingFlow(true);
    try {
      const response = await fetch("/api/admin/flows", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          tenantId: subscription.tenant.id,
          name: `${subscription.tenant.name} Flow`,
        }),
      });

      if (response.ok) {
        const result = await response.json();
        toast.success("Flow created successfully");
        router.push(`/admin/flows/${result.flow.id}/edit`);
      } else {
        toast.error("Failed to create flow");
      }
    } catch (error) {
      console.error("Error creating flow:", error);
      toast.error("Error creating flow");
    } finally {
      setCreatingFlow(false);
    }
  };


  if (loading) {
    return (
      <div className="flex h-96 items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  if (!data) {
    return (
      <div className="text-center py-12">
        <h2 className="text-2xl font-bold">Subscriber not found</h2>
        <Button
          variant="link"
          onClick={() => router.push("/admin/subscribers")}
          className="mt-4"
        >
          <ArrowLeft className="mr-2 h-4 w-4" /> Back to list
        </Button>
      </div>
    );
  }

  const { subscription, executionLogs } = data;

  return (
    <div className="space-y-6 pb-12">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button
            variant="outline"
            size="icon"
            onClick={() => router.push("/admin/subscribers")}
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold tracking-tight">
              {subscription.tenant.name}
            </h1>
            <p className="text-muted-foreground">Manage subscriber account and configurations</p>
          </div>
        </div>
        <Badge variant={subscription.status === "active" ? "default" : "secondary"}>
          {subscription.status.toUpperCase()}
        </Badge>
      </div>

      <Tabs
        value={activeTab}
        onValueChange={(value) => {
          const params = new URLSearchParams(searchParams.toString());
          params.set("tab", value);
          router.push(`/admin/subscribers/${id}?${params.toString()}`);
        }}
        className="space-y-4"
      >
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="subscription">Subscription</TabsTrigger>
          <TabsTrigger value="bots">Bots & Channels</TabsTrigger>
          <TabsTrigger value="flows">Flows</TabsTrigger>
          <TabsTrigger value="logs">Logs & Activity</TabsTrigger>
        </TabsList>

        <TabsContent value="overview">
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Tenant ID</CardTitle>
                <Shield className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold truncate">{subscription.tenant.id}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Active Plan</CardTitle>
                <CreditCard className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{subscription.plan.name}</div>
                <p className="text-xs text-muted-foreground">
                  ${subscription.plan.price}/month
                </p>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Users</CardTitle>
                <User className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{subscription.tenant.users.length}</div>
              </CardContent>
            </Card>
          </div>

          <Card className="mt-4">
            <CardHeader>
              <CardTitle>Users</CardTitle>
              <CardDescription>Manage users and permissions for this tenant</CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Email</TableHead>
                    <TableHead>Role</TableHead>
                    <TableHead>Joined</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {subscription.tenant.users.map((user) => (
                    <TableRow key={user.id}>
                      <TableCell className="font-medium">{user.name || "N/A"}</TableCell>
                      <TableCell>{user.email}</TableCell>
                      <TableCell>
                        <Badge variant={user.isAdmin ? "default" : "secondary"}>
                          {user.isAdmin ? "Admin" : "User"}
                        </Badge>
                      </TableCell>
                      <TableCell>{new Date(user.createdAt).toLocaleDateString()}</TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleToggleUserAdmin(user.id, user.isAdmin)}
                        >
                          {user.isAdmin ? "Revoke Admin" : "Make Admin"}
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="subscription">
          <Card>
            <CardHeader>
              <CardTitle>Subscription Management</CardTitle>
              <CardDescription>Modify plan, status, and billing details</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="plan">Plan</Label>
                  <Select value={planId} onValueChange={setPlanId}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select a plan" />
                    </SelectTrigger>
                    <SelectContent>
                      {plans.map((p) => (
                        <SelectItem key={p.id} value={p.id}>
                          {p.name} - ${p.price}/mo
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="status">Status</Label>
                  <Select value={status} onValueChange={setStatus}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select status" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="active">Active</SelectItem>
                      <SelectItem value="trialing">Trialing</SelectItem>
                      <SelectItem value="canceled">Canceled</SelectItem>
                      <SelectItem value="incomplete">Incomplete</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="periodEnd">Current Period End</Label>
                  <Input
                    id="periodEnd"
                    type="date"
                    value={periodEnd}
                    onChange={(e) => setPeriodEnd(e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Stripe ID</Label>
                  <div className="flex items-center gap-2">
                    <Input value={subscription.stripeId || "No Stripe ID"} readOnly />
                    {subscription.stripeId && (
                      <Button variant="outline" size="icon" asChild>
                        <a
                          href={`https://dashboard.stripe.com/subscriptions/${subscription.stripeId}`}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </Button>
                    )}
                  </div>
                </div>
              </div>
              <div className="flex justify-end">
                <Button onClick={handleUpdateSubscription} disabled={saving}>
                  {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                  <Save className="mr-2 h-4 w-4" />
                  Save Changes
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="bots">
          <Card>
            <CardHeader>
              <CardTitle>Bots & Channels</CardTitle>
              <CardDescription>View connected bots and communication channels</CardDescription>
            </CardHeader>
            <CardContent>
              {subscription.tenant.bots.length === 0 ? (
                <p className="text-center text-muted-foreground py-8">No bots configured</p>
              ) : (
                <div className="space-y-6">
                  {subscription.tenant.bots.map((bot) => (
                    <div key={bot.id} className="border rounded-lg p-4">
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-2">
                          <Bot className="h-5 w-5 text-blue-500" />
                          <h3 className="font-bold">{bot.name}</h3>
                          <Badge variant={bot.enabled ? "default" : "secondary"}>
                            {bot.enabled ? "Enabled" : "Disabled"}
                          </Badge>
                        </div>
                        <span className="text-xs text-muted-foreground">ID: {bot.id}</span>
                      </div>
                      <div className="grid gap-4 sm:grid-cols-2 md:grid-cols-3">
                        {bot.channels.map((channel) => (
                          <div key={channel.id} className="flex items-center gap-2 text-sm p-2 bg-muted rounded">
                            <Badge variant={channel.isActive ? "outline" : "secondary"}>
                              {channel.type}
                            </Badge>
                            <span className={channel.isActive ? "text-foreground" : "text-muted-foreground"}>
                              {channel.isActive ? "Active" : "Inactive"}
                            </span>
                          </div>
                        ))}
                        {bot.channels.length === 0 && (
                          <p className="text-xs text-muted-foreground">No channels assigned</p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="flows">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <div>
                <CardTitle>Conversational Flows</CardTitle>
                <CardDescription>View and manage flows assigned to this subscriber</CardDescription>
              </div>
              <Button onClick={handleCreateFlow} disabled={creatingFlow} size="sm">
                {creatingFlow ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Plus className="mr-2 h-4 w-4" />
                )}
                Add New Flow
              </Button>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Flow Name</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Sessions</TableHead>
                    <TableHead>Leads</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {subscription.tenant.flows.map((flow) => (
                    <TableRow key={flow.id}>
                      <TableCell className="font-medium">{flow.name}</TableCell>
                      <TableCell>
                        <Badge variant={flow.isActive ? "default" : "secondary"}>
                          {flow.isActive ? "Active" : "Inactive"}
                        </Badge>
                      </TableCell>
                      <TableCell>{flow._count.sessions}</TableCell>
                      <TableCell>{flow._count.leads}</TableCell>
                      <TableCell className="text-right">
                        <Button variant="ghost" size="sm" asChild>
                          <a href={`/admin/flows/${flow.id}/edit`} target="_blank" rel="noopener noreferrer">
                            <ExternalLink className="h-4 w-4" />
                          </a>
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                  {subscription.tenant.flows.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} className="text-center text-muted-foreground py-8">
                        No flows created
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="logs">
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Recent Activity</CardTitle>
                <CardDescription>Audit trail of actions taken by users</CardDescription>
              </CardHeader>
              <CardContent>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Time</TableHead>
                      <TableHead>Type</TableHead>
                      <TableHead>Description</TableHead>
                      <TableHead>User</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {subscription.tenant.activityLogs.map((log) => (
                      <TableRow key={log.id}>
                        <TableCell className="text-xs whitespace-nowrap">
                          {new Date(log.createdAt).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline" className="capitalize">
                            {log.type.replace("_", " ")}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <div className="font-medium text-sm">{log.title}</div>
                          <div className="text-xs text-muted-foreground">{log.description}</div>
                        </TableCell>
                        <TableCell className="text-sm">
                          {log.user?.name || log.user?.email || "System"}
                        </TableCell>
                      </TableRow>
                    ))}
                    {subscription.tenant.activityLogs.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={4} className="text-center text-muted-foreground py-8">
                          No recent activity
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Execution Logs</CardTitle>
                <CardDescription>Recent bot executions and interactions</CardDescription>
              </CardHeader>
              <CardContent>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Time</TableHead>
                      <TableHead>Bot</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>Direction</TableHead>
                      <TableHead>User</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {executionLogs.map((log) => (
                      <TableRow key={log.id}>
                        <TableCell className="text-xs whitespace-nowrap">
                          {new Date(log.createdAt).toLocaleString()}
                        </TableCell>
                        <TableCell className="font-medium text-sm">{log.bot.name}</TableCell>
                        <TableCell>
                          <Badge variant={log.status === "success" ? "default" : "destructive"}>
                            {log.status}
                          </Badge>
                          {log.errorMessage && (
                            <div className="text-[10px] text-red-500 mt-1 max-w-[200px] truncate">
                              {log.errorMessage}
                            </div>
                          )}
                        </TableCell>
                        <TableCell className="text-xs capitalize">{log.direction}</TableCell>
                        <TableCell className="text-sm">
                          {log.user?.name || log.user?.email || "Anonymous"}
                        </TableCell>
                      </TableRow>
                    ))}
                    {executionLogs.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={5} className="text-center text-muted-foreground py-8">
                          No recent executions
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { 
  Loader2, 
  Search, 
  Trash2, 
  Calendar, 
  Eye, 
  ChevronLeft, 
  ChevronRight,
  Filter
} from "lucide-react";
import { toast } from "sonner";
import Link from "next/link";
import { useConfirmation } from "@/components/ui/confirmation-provider";
import { Skeleton } from "@/components/ui/skeleton";

export const dynamic = "force-dynamic";

interface Subscriber {
  id: string;
  tenantId: string;
  status: string;
  stripeId: string | null;
  currentPeriodStart: string | null;
  currentPeriodEnd: string | null;
  cancelAtPeriodEnd: boolean;
  createdAt: string;
  updatedAt: string;
  plan: {
    id: string;
    name: string;
    price: number;
  };
  tenant: {
    id: string;
    name: string;
    users: Array<{
      id: string;
      email: string | null;
      name: string | null;
    }>;
  };
}

interface PaginationData {
  total: number;
  page: number;
  limit: number;
  totalPages: number;
}

export default function SubscribersPage() {
  const { confirm } = useConfirmation();
  const [subscribers, setSubscribers] = useState<Subscriber[]>([]);
  const [pagination, setPagination] = useState<PaginationData | null>(null);
  const [loading, setLoading] = useState(true);

  // Filters
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [page, setPage] = useState(1);
  const [limit] = useState(10);

  const fetchSubscribers = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: page.toString(),
        limit: limit.toString(),
      });

      if (searchTerm) params.append("search", searchTerm);
      if (statusFilter !== "all") params.append("status", statusFilter);

      const response = await fetch(`/api/admin/subscribers?${params.toString()}`);
      const data = await response.json();

      if (response.ok) {
        setSubscribers(data.subscribers);
        setPagination(data.pagination);
      } else {
        toast.error(data.error || "Failed to fetch subscribers", {
          description: data.code ? `Error Code: ${data.code}` : undefined
        });
      }
    } catch (error: any) {
      console.error("Error fetching subscribers:", error);
      toast.error("Error loading subscribers", { description: error.message });
    } finally {
      setLoading(false);
    }
  }, [page, limit, searchTerm, statusFilter]);

  useEffect(() => {
    const timer = setTimeout(() => {
      fetchSubscribers();
    }, 300);
    return () => clearTimeout(timer);
  }, [fetchSubscribers]);

  const handleDelete = async (subscriberId: string) => {
    const confirmed = await confirm({
      title: "Delete Subscription",
      description: "Are you sure you want to delete this subscription? This action cannot be undone.",
      confirmText: "Delete",
      variant: "destructive",
    });

    if (!confirmed) {
      return;
    }

    try {
      const response = await fetch(`/api/admin/subscribers/${subscriberId}`, {
        method: "DELETE",
      });

      if (response.ok) {
        toast.success("Subscription deleted successfully");
        fetchSubscribers();
      } else {
        const data = await response.json();
        toast.error(data.error || "Failed to delete subscription");
      }
    } catch (error: any) {
      console.error("Error deleting subscription:", error);
      toast.error("Error deleting subscription", { description: error.message });
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "active":
        return "bg-green-100 text-green-800 border-green-200 hover:bg-green-100";
      case "trialing":
        return "bg-blue-100 text-blue-800 border-blue-200 hover:bg-blue-100";
      case "canceled":
        return "bg-red-100 text-red-800 border-red-200 hover:bg-red-100";
      case "incomplete":
        return "bg-yellow-100 text-yellow-800 border-yellow-200 hover:bg-yellow-100";
      default:
        return "bg-gray-100 text-gray-800 border-gray-200 hover:bg-gray-100";
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold tracking-tight">Subscriber Management</h2>
        <p className="text-muted-foreground">
          View and manage active paid subscriptions and billing status.
        </p>
      </div>

      {/* Filters Bar */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search workspace, name or email..."
                className="pl-9"
                value={searchTerm}
                onChange={(e) => {
                  setSearchTerm(e.target.value);
                  setPage(1);
                }}
              />
            </div>
            <div className="w-full md:w-[200px]">
              <Select value={statusFilter} onValueChange={(val) => {
                setStatusFilter(val);
                setPage(1);
              }}>
                <SelectTrigger>
                  <Filter className="h-4 w-4 mr-2 text-muted-foreground" />
                  <SelectValue placeholder="Filter by status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Active/Paid</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="trialing">Trialing</SelectItem>
                  <SelectItem value="past_due">Past Due</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Paid Subscriptions</CardTitle>
          <CardDescription>
            {pagination ? `Total ${pagination.total} paid subscriptions managed` : "Loading subscriptions..."}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Customer</TableHead>
                <TableHead>Primary User</TableHead>
                <TableHead>Plan</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Current Period</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <TableRow key={i}>
                    <TableCell><Skeleton className="h-6 w-[150px]" /></TableCell>
                    <TableCell><Skeleton className="h-10 w-[200px]" /></TableCell>
                    <TableCell><Skeleton className="h-6 w-[80px]" /></TableCell>
                    <TableCell><Skeleton className="h-6 w-[100px]" /></TableCell>
                    <TableCell><Skeleton className="h-6 w-[120px]" /></TableCell>
                    <TableCell className="text-right"><Skeleton className="h-8 w-[80px] ml-auto" /></TableCell>
                  </TableRow>
                ))
              ) : subscribers.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="h-24 text-center">
                    No subscriptions found.
                  </TableCell>
                </TableRow>
              ) : (
                subscribers.map((sub) => (
                  <TableRow key={sub.id}>
                    <TableCell className="font-medium">
                      {sub.tenant.name}
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span className="text-sm font-medium">{sub.tenant.users[0]?.name || "—"}</span>
                        <span className="text-xs text-muted-foreground">{sub.tenant.users[0]?.email || "No email"}</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-col">
                        <span className="font-medium capitalize">{sub.plan.name}</span>
                        <span className="text-xs text-muted-foreground">£{sub.plan.price}/mo</span>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className={`${getStatusColor(sub.status)} border-transparent font-semibold`}>
                        {sub.status.toUpperCase()}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {sub.currentPeriodEnd ? (
                        <div className="text-xs">
                          <div className="flex items-center gap-1 font-medium">
                            <Calendar className="h-3 w-3" />
                            {new Date(sub.currentPeriodEnd).toLocaleDateString()}
                          </div>
                          {sub.cancelAtPeriodEnd && (
                            <span className="text-red-500 font-semibold">
                              Cancels at end
                            </span>
                          )}
                        </div>
                      ) : (
                        "—"
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button variant="ghost" size="icon" asChild title="View Details">
                          <Link href={`/admin/subscribers/${sub.id}`}>
                            <Eye className="h-4 w-4" />
                          </Link>
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleDelete(sub.id)}
                          className="text-red-500 hover:text-red-700 hover:bg-red-50"
                          title="Delete Subscription"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>

          {/* Pagination Controls */}
          {pagination && pagination.totalPages > 1 && (
            <div className="flex items-center justify-between space-x-2 py-4 border-t mt-4">
              <div className="text-sm text-muted-foreground">
                Page {pagination.page} of {pagination.totalPages}
              </div>
              <div className="flex space-x-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page === 1 || loading}
                >
                  <ChevronLeft className="h-4 w-4 mr-1" />
                  Previous
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage((p) => Math.min(pagination.totalPages, p + 1))}
                  disabled={page === pagination.totalPages || loading}
                >
                  Next
                  <ChevronRight className="h-4 w-4 ml-1" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

