source:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import {
  AlertTriangle,
  CheckCircle2,
  Copy,
  Eye,
  EyeOff,
  ExternalLink,
  Globe,
  KeyRound,
  Loader2,
  Plus,
  RefreshCw,
  Save,
  X,
} from "lucide-react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useConfirmation } from "@/components/ui/confirmation-provider";
import {
  ChannelGuidanceCard,
  ChannelPageHeader,
} from "@/components/channels/channel-ui";
import { ChannelFlowAssignmentCard } from "@/components/channels/channel-sections";

export const dynamic = "force-dynamic";

type Bot = {
  id: string;
  name: string;
  entryFlow?: string | null;
};

type FlowOption = {
  id: string;
  name: string;
  isActive: boolean;
};

type ChannelFlowAssignment = {
  id: string;
  flowId: string;
  flow?: {
    id: string;
    name: string;
    isActive: boolean;
  };
};

type Channel = {
  id: string;
  name: string;
  type: string;
  channelId?: string | null;
  config?: {
    title?: string;
    primaryColor?: string;
    welcomeMessage?: string;
    position?: "left" | "right";
    [key: string]: unknown;
  };
  flowAssignments?: ChannelFlowAssignment[];
};

type PreviewMessage = {
  id: string;
  role: "user" | "bot";
  text: string;
};

type WebchatSite = {
  id: string;
  name: string;
  publicKey: string;
  secretKey: string;
  allowedDomains: string[];
  themeConfig?: {
    title?: string;
    primaryColor?: string;
    welcomeMessage?: string;
    position?: "left" | "right";
    [key: string]: unknown;
  };
  channelId?: string | null;
  isActive: boolean;
};

type WebchatDiagnostics = {
  lastPingAt: string | null;
  blockedOriginCount: number;
  rateLimitCount: number;
  recentErrors: Array<{
    id: string;
    createdAt: string;
    reason: string;
    stage: string | null;
    message: string | null;
  }>;
};

