                  The current dashboard origin {origin || "(unknown)"} is not on
                  this site&apos;s allowlist. The harness will surface the same
                  blocked-origin behavior until you add this origin or test from
                  an allowed domain.
                </p>
              ) : null}
            </div>
          ) : null}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Embed Snippet</CardTitle>
          <CardDescription>
            Paste this in your website HTML before the closing body tag. This snippet prefers your webchat public key when available.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <SnippetTabs
            type="embed"
            html={embedSnippet || "Select a bot and web channel to generate the embed snippet."}
            react={getReactEmbedSnippet()}
            nextjs={getNextJsEmbedSnippet()}
            label="Embed Snippet"
          />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Lead Form Snippet</CardTitle>
          <CardDescription>
            Paste this where you want a simple enquiry form. It submits to the public leads endpoint and triggers the same lead dashboard and notification flow.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <SnippetTabs
            type="lead"
            html={leadFormSnippet || "Save or load a webchat site to generate the lead form snippet."}
            react={getReactLeadFormSnippet()}
            nextjs={getNextJsLeadFormSnippet()}
            label="Lead Form Snippet"
          />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Diagnostics</CardTitle>
          <CardDescription>
            Recent site activity, blocked origins, and rate-limit signals for
            the selected webchat site.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 md:grid-cols-3">
            <div className="rounded-lg border bg-slate-50 p-4">
              <p className="text-sm text-muted-foreground">Last Ping</p>
              <p className="mt-2 text-sm font-medium text-slate-900">
                {isDiagnosticsLoading
                  ? "Loading..."
                  : diagnostics?.lastPingAt
                    ? new Date(diagnostics.lastPingAt).toLocaleString()
                    : "No activity yet"}
              </p>
            </div>
            <div className="rounded-lg border bg-slate-50 p-4">
              <p className="text-sm text-muted-foreground">Blocked Origins</p>
              <p className="mt-2 text-2xl font-semibold text-slate-900">
                {diagnostics?.blockedOriginCount ?? 0}
              </p>
            </div>
            <div className="rounded-lg border bg-slate-50 p-4">
              <p className="text-sm text-muted-foreground">Rate-Limit Events</p>
              <p className="mt-2 text-2xl font-semibold text-slate-900">
                {diagnostics?.rateLimitCount ?? 0}
              </p>
            </div>
          </div>

          <div className="space-y-3">
            <h3 className="text-sm font-medium text-slate-900">
              Recent Errors
            </h3>
            {isDiagnosticsLoading ? (
              <p className="text-sm text-muted-foreground">
                Loading diagnostics...
              </p>
            ) : diagnostics?.recentErrors?.length ? (
              <div className="space-y-2">
                {diagnostics.recentErrors.map((entry) => (
                  <div key={entry.id} className="rounded-lg border p-3">
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <p className="text-sm font-medium text-slate-900">
                        {entry.reason.replace(/_/g, " ")}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {new Date(entry.createdAt).toLocaleString()}
                      </p>
                    </div>
                    <p className="mt-1 text-xs text-muted-foreground">
                      {entry.stage
                        ? `Stage: ${entry.stage}`
                        : "Stage unavailable"}
                    </p>
                    {entry.message ? (
                      <p className="mt-2 text-sm text-slate-700">
                        {entry.message}
                      </p>
                    ) : null}
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">
                No diagnostics events recorded for this site yet.
              </p>
            )}
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between gap-3">
            <div>
              <CardTitle>Live Preview</CardTitle>
              <CardDescription>
                Real-time preview of your widget style before embedding.
              </CardDescription>
            </div>
            <Button variant="outline" size="sm" onClick={handleResetPreview}>
              Reset Preview
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="relative h-96 rounded-lg border bg-slate-50 p-4 overflow-hidden">
            <div
              className={`absolute bottom-4 ${position === "left" ? "left-4" : "right-4"
                } w-[280px] max-w-[90%]`}
            >
              {isPreviewOpen && (
                <div className="overflow-hidden rounded-xl border bg-white shadow-xl">
                  <div
                    className="flex items-center justify-between px-3 py-2 text-sm font-semibold text-white"
                    style={{ backgroundColor: previewColor }}
                  >
                    <span>{previewTitle}</span>
                    <button
                      type="button"
                      onClick={() => setIsPreviewOpen(false)}
                      className="rounded px-2 py-1 text-xs font-semibold hover:bg-black/15"
                    >
                      Close
                    </button>
                  </div>

                  <div className="space-y-2 bg-slate-100 p-3">
                    <div className="max-w-[85%] rounded-xl border bg-white px-3 py-2 text-sm text-slate-900">
                      {previewWelcomeMessage}
                    </div>
                    {previewMessages.map((message) => (
                      <div
                        key={message.id}
                        className={
                          message.role === "user"
                            ? "ml-auto max-w-[85%] rounded-xl bg-slate-900 px-3 py-2 text-sm text-white"
                            : "max-w-[85%] rounded-xl border bg-white px-3 py-2 text-sm text-slate-900"
                        }
                      >
                        {message.text}
                      </div>
                    ))}
                  </div>

                  <div className="flex items-center gap-2 border-t bg-white p-2">
                    <input
                      type="text"
                      value={previewDraft}
                      onChange={(event) => setPreviewDraft(event.target.value)}
                      onKeyDown={(event) => {
                        if (event.key === "Enter") {
                          event.preventDefault();
                          handlePreviewSend();
                        }
                      }}
                      placeholder="Type your message..."
                      className="h-9 flex-1 rounded-md border bg-white px-3 py-2 text-xs text-slate-900 placeholder:text-slate-400 outline-none"
                    />
                    <button
                      type="button"
                      onClick={handlePreviewSend}
                      className="h-9 rounded-md px-3 text-sm font-semibold text-white"
                      style={{ backgroundColor: previewColor }}
                    >
                      Send
                    </button>
                  </div>
                </div>
              )}

              <button
                type="button"
                onClick={() => setIsPreviewOpen((value) => !value)}
                className={`mt-3 h-12 w-12 rounded-full text-sm font-semibold text-white shadow-lg flex items-center justify-center ${position === "left" ? "mr-auto" : "ml-auto"
                  }`}
                style={{ backgroundColor: previewColor }}
              >
                {isPreviewOpen ? "Hide" : "Chat"}
              </button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div >
  );
}

function SnippetTabs({
  type,
  html,
  react,
  nextjs,
  label,
}: {
  type: "embed" | "lead";
  html: string;
  react: string;
  nextjs: string;
  label: string;
}) {
  const [tab, setTab] = useState<"html" | "react" | "nextjs">("html");

  const snippet = tab === "html" ? html : tab === "react" ? react : nextjs;

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(snippet);
      toast.success(`${label} copied!`);
    } catch {
      toast.error(`Failed to copy ${label.toLowerCase()}`);
    }
  };

  return (
    <div>
      <div className="mb-3 flex items-center justify-between">
        <div className="flex flex-wrap gap-2">
          <Button
            type="button"
            size="sm"
            variant={tab === "html" ? "default" : "outline"}
            onClick={() => setTab("html")}
          >
            HTML
          </Button>
          <Button
            type="button"
            size="sm"
            variant={tab === "react" ? "default" : "outline"}
            onClick={() => setTab("react")}
          >
            React
          </Button>
          <Button
            type="button"
            size="sm"
            variant={tab === "nextjs" ? "default" : "outline"}
            onClick={() => setTab("nextjs")}
          >
            Next.js
          </Button>
        </div>
        <Button
          type="button"
          size="sm"
          variant="outline"
          onClick={handleCopy}
        >
          <Copy className="mr-2 h-4 w-4" /> Copy Snippet
        </Button>
      </div>
      <Textarea
        value={snippet}
        readOnly
        rows={type === "lead" ? 14 : 10}
        className="font-mono text-xs"
      />
    </div>
  );
}

