] as const;

type PlanName = (typeof PLANS)[number]["name"];

function parsePlanName(value: string | null): PlanName | null {
  if (!value) {
    return null;
  }

  const normalized = value.trim().toLowerCase();
  if (
    normalized === "free" ||
    normalized === "starter" ||
    normalized === "pro" ||
    normalized === "business"
  ) {
    return normalized;
  }

  return null;
}

function PricingContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [loading, setLoading] = useState<string | null>(null);
  const [currentSubscription, setCurrentSubscription] = useState<any>(null);
  const [selectedPlan, setSelectedPlan] = useState<(typeof PLANS)[number] | null>(null);
  const preferredPlan = parsePlanName(searchParams.get("plan")) || "pro";
  const source = searchParams.get("source");

  useEffect(() => {
    setClarityTags({
      page_type: "pricing",
      funnel_step: "landing",
    });

    trackEvent("pricing_viewed", {
      onceKey: "pricing_viewed",
      onceScope: "session",
      properties: { origin: "app" },
    });

    const fetchCurrentSub = async () => {
      try {
        const res = await fetch("/api/billing/subscription");
        if (res.ok) {
          const data = await res.json();
          setCurrentSubscription(data.subscription);
        }
      } catch (err) {
        console.error("Failed to fetch subscription", err);
      }
    };
    fetchCurrentSub();
  }, []);

  const handleSubscribeClick = (planName: string) => {
    const plan = PLANS.find((p) => p.name === planName);
    if (!plan) return;

    if (planName === "free") {
      if (currentSubscription?.plan?.name === "free") {
        toast.info("You are already on the Free plan");
        router.push("/");
      } else {
        router.push("/");
      }
      return;
    }

    setSelectedPlan(plan);
  };

  const handleConfirmCheckout = async () => {
    if (!selectedPlan) return;
    const planName = selectedPlan.name;

    trackEvent("get_started_click", {
      properties: {
        plan: planName,
        source: "pricing_table",
        origin: "app",
      },
    });

    trackEvent("subscription_started", {
      properties: {
        plan: planName,
      },
    });

    setLoading(planName);
    setSelectedPlan(null);

    try {
      const response = await fetch("/api/billing/checkout", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          planName,
          priceId: getPriceId(planName),
        }),
      });

      if (!response.ok) {
        if (response.status === 401) {
          toast.error("Please login to subscribe");
