import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { stripe } from "@/lib/stripe";

export const dynamic = 'force-dynamic';

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const tenantId = session.user.tenantId;
    if (!tenantId) {
      return NextResponse.json({ error: "No tenant found" }, { status: 403 });
    }

    const { feedback, type } = await req.json().catch(() => ({ feedback: "", type: "CANCEL" }));

    if (feedback) {
      console.log(
        `[Subscription Feedback] ${type} from tenant ${tenantId}: ${feedback}`,
      );
      await prisma.churnFeedback.create({
        data: {
          tenantId,
          userId: session.user.id,
          type: type || "CANCEL",
          reason: feedback,
        },
      });

      // If it's just feedback for downgrade, we don't proceed with cancellation logic
      if (type === "DOWNGRADE") {
        return NextResponse.json({ message: "Feedback recorded" });
      }
    }

    const subscription = await prisma.subscription.findUnique({
      where: { tenantId },
      include: { plan: true },
    });

    if (!subscription) {
      return NextResponse.json(
        { error: "Subscription not found" },
        { status: 404 },
      );
    }

    // Handle FREE plans or no stripe ID
    if (
      !stripe ||
      !subscription.stripeId ||
      subscription.stripeId.startsWith("free_")
    ) {
      const updated = await prisma.subscription.update({
        where: { id: subscription.id },
        data: {
          status: "CANCELED",
          cancelAtPeriodEnd: true,
        },
      });
      return NextResponse.json({ subscription: updated });
    }

    // Set cancel_at_period_end = true in Stripe
    const stripeSub = await stripe.subscriptions.update(subscription.stripeId, {
      cancel_at_period_end: true,
    });

    const updated = await prisma.subscription.update({
      where: { id: subscription.id },
      data: {
        status: (stripeSub as any).status.toUpperCase(),
        cancelAtPeriodEnd: (stripeSub as any).cancel_at_period_end,
        currentPeriodEnd: (stripeSub as any).current_period_end 
          ? new Date((stripeSub as any).current_period_end * 1000) 
          : new Date(),
      },
    });

    return NextResponse.json({
        message: "Subscription set to cancel at period end",
        subscription: updated
    });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("[Subscription Cancel] Error:", error);
    return NextResponse.json(
      { error: "Internal Server Error", details: message },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { randomUUID } from "node:crypto";
import { authOptions } from "@/lib/auth";
import { stripe } from "@/lib/stripe";
import { prisma } from "@/lib/prisma";
import { z } from "zod";

export const dynamic = 'force-dynamic';




const checkoutRequestSchema = z.object({
  priceId: z.string().min(1),
  planName: z.string().optional(),
});

export async function POST(req: NextRequest) {
  try {
    if (!stripe) {
      return NextResponse.json(
        { error: "Billing service unavailable" },
        { status: 503 },
      );
    }

    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const parsedBody = checkoutRequestSchema.safeParse(await req.json());

    if (!parsedBody.success) {
      return NextResponse.json(
        { error: "Invalid request body" },
        { status: 400 },
      );
    }

    const { priceId, planName } = parsedBody.data;

    const userId = session.user.id;
    const tenantId = session.user.tenantId;
    const appUrl = process.env.NEXT_PUBLIC_APP_URL;

    if (!tenantId) {
      return NextResponse.json({ error: "Tenant ID missing" }, { status: 400 });
    }

    if (!appUrl) {
      return NextResponse.json(
        { error: "Billing configuration error" },
        { status: 500 },
      );
    }

    // 1. Resolve Stripe Customer
    // Identity Handling: Reuse customer if email exists (Rule #9)
    const tenant = await prisma.tenant.findUnique({
      where: { id: tenantId },
      include: { subscriptions: true },
    });

    if (!tenant) {
      return NextResponse.json({ error: "Tenant not found" }, { status: 404 });
    }

    let stripeCustomerId = tenant.subscriptions?.stripeCustomerId;

    if (!stripeCustomerId && session.user.email) {
      const existingCustomers = await stripe.customers.list({
        email: session.user.email.toLowerCase(),
        limit: 1,
      });

      if (existingCustomers.data.length > 0) {
        stripeCustomerId = existingCustomers.data[0].id;
      }
    }

    if (!stripeCustomerId) {
      const customer = await stripe.customers.create({
        email: session.user.email || undefined,
        name: session.user.name || undefined,
        metadata: {
          userId,
          tenantId,
        },
      });
      stripeCustomerId = customer.id;
    }

    // 2. Prevent Trial Abuse (Rule #2)
    // Check if this tenant has already used a trial
    const hasUsedTrial = tenant.trialUsed;
    const trialDays = hasUsedTrial ? undefined : 14;

    const metadata: Record<string, string> = {
      userId,
      tenantId,
    };

    if (planName) {
      metadata.planName = planName;
    }

    // 3. Create Checkout Session
    // Redesign: Use /billing/success with session_id for reliable sync (Step 3)
    const checkoutSession = await stripe.checkout.sessions.create({
      customer: stripeCustomerId,
      line_items: [
        {
          price: priceId,
          quantity: 1,
        },
      ],
      mode: "subscription",
      allow_promotion_codes: true,
      // Pass CHECKOUT_SESSION_ID to our success page for verification
      success_url: `${appUrl}/billing/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${appUrl}/pricing?canceled=true`,
      metadata,
      subscription_data: {
        metadata,
        trial_period_days: trialDays,
      },
    });

    return NextResponse.json({ url: checkoutSession.url });
  } catch (error) {
    console.error("[Stripe Checkout] Error:", error);
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { stripe } from "@/lib/stripe";

export const dynamic = 'force-dynamic';




export async function DELETE(
  req: NextRequest,
  context: { params: Promise<{ id: string }> },
) {
  try {
    // Safely try to parse body if it exists (for feedback)
    let feedback = "";
    try {
      const body = await req.json();
      feedback = body.feedback || "";
    } catch (e) {
      // Body might be empty
    }

    if (feedback) {
      console.log(`[Subscription Cancel] Feedback from user: ${feedback}`);
    }
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { id } = await context.params;

    const subscription = await prisma.subscription.findFirst({
      where: {
        id,
        tenantId: session.user.tenantId,
      },
    });

    if (!subscription) {
      return NextResponse.json(
        { error: "Subscription not found" },
        { status: 404 },
      );
    }

    if (
      !stripe ||
      !subscription.stripeId ||
      subscription.stripeId.startsWith("free_")
    ) {
      const updated = await prisma.subscription.update({
        where: { id: subscription.id },
        data: {
          status: "canceled",
          cancelAtPeriodEnd: true,
        },
      });
      return NextResponse.json({ subscription: updated });
    }

    const stripeSub = await stripe.subscriptions.update(subscription.stripeId, {
      cancel_at_period_end: true,
    });

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const sub = stripeSub as any;
    const updated = await prisma.subscription.update({
      where: { id: subscription.id },
      data: {
        status: sub.status,
        cancelAtPeriodEnd: sub.cancel_at_period_end,
        currentPeriodEnd: new Date(sub.current_period_end * 1000),
      },
    });

    return NextResponse.json({ subscription: updated });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error("[Subscription Cancel] Error:", error);
    return NextResponse.json(
      { error: "Internal Server Error", details: message },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { headers } from "next/headers";
import { stripe } from "@/lib/stripe";
import { prisma } from "@/lib/prisma";
import Stripe from "stripe";
import { syncSubscription } from "@/lib/billing-service";

export const dynamic = 'force-dynamic';

export async function POST(req: NextRequest) {
  const body = await req.text();
  const headersList = await headers();
  const signature = headersList.get("stripe-signature") as string;

  let event: Stripe.Event;

  try {
    if (!process.env.STRIPE_WEBHOOK_SECRET) {
      throw new Error("STRIPE_WEBHOOK_SECRET not configured");
    }
    event = stripe!.webhooks.constructEvent(
      body,
      signature,
      process.env.STRIPE_WEBHOOK_SECRET,
    );
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : "Unknown error";
    console.error(`[Webhook] Signature verification failed: ${errorMessage}`);
    return NextResponse.json({ error: "Webhook Error" }, { status: 400 });
  }

  // Idempotency & Audit Check (Rule #8)
  const existingEvent = await prisma.stripeEvent.findUnique({
    where: { stripeEventId: event.id },
  });

  if (existingEvent && existingEvent.status === "PROCESSED") {
    return NextResponse.json({ received: true, duplicate: true });
  }

  // Log event for audit
  const auditLog = await prisma.stripeEvent.upsert({
    where: { stripeEventId: event.id },
    create: {
      stripeEventId: event.id,
      type: event.type,
      status: "PENDING",
      metadata: event.data.object as any,
    },
    update: {},
  });

  try {
    switch (event.type) {
      case "checkout.session.completed": {
        const session = event.data.object as Stripe.Checkout.Session;
        const tenantId = session.metadata?.tenantId;
        const subscriptionId = session.subscription as string;

        if (tenantId && subscriptionId) {
          await syncSubscription(tenantId, subscriptionId);
        }
        break;
      }

      case "customer.subscription.created":
      case "customer.subscription.updated":
      case "customer.subscription.deleted": {
        const subscription = event.data.object as Stripe.Subscription;
        const dbSub = await prisma.subscription.findUnique({
          where: { stripeCustomerId: subscription.customer as string },
        });

        if (dbSub) {
          await syncSubscription(dbSub.tenantId, subscription.id);
        }
        break;
      }

      case "invoice.payment_succeeded": {
        const invoice = event.data.object as Stripe.Invoice;
        if (invoice.subscription) {
          const dbSub = await prisma.subscription.findUnique({
            where: { stripeCustomerId: invoice.customer as string },
          });

          if (dbSub) {
            await syncSubscription(dbSub.tenantId, invoice.subscription as string);

            // Rule #8: Idempotent Revenue Tracking
            await prisma.revenue.upsert({
              where: { stripeInvoiceId: invoice.id },
              create: {
                stripeInvoiceId: invoice.id,
                stripeSubscriptionId: invoice.subscription as string,
                tenantId: dbSub.tenantId,
                amount: invoice.amount_paid, // Cents from Stripe
                currency: invoice.currency.toUpperCase(),
                status: "paid",
                paidAt: new Date(invoice.status_transitions.paid_at! * 1000),
                metadata: {
                  invoice_pdf: invoice.invoice_pdf,
                  number: invoice.number,
                },
              },
              update: {
                status: "paid",
                paidAt: new Date(invoice.status_transitions.paid_at! * 1000),
              },
            });
            console.log(`[Webhook] Revenue recorded for tenant ${dbSub.tenantId}: ${invoice.amount_paid} ${invoice.currency}`);
          }
        }
        break;
      }

      case "invoice.payment_failed": {
        const invoice = event.data.object as any;
        const dbSub = await prisma.subscription.findUnique({
          where: { stripeCustomerId: invoice.customer as string },
        });

        if (dbSub) {
          // Rule #3: Handle failed payments -> PAST_DUE
          await prisma.subscription.update({
            where: { id: dbSub.id },
            data: { status: "PAST_DUE" },
          });
          console.warn(`[Webhook] Payment failed for tenant ${dbSub.tenantId}. Status set to PAST_DUE.`);
        }
        break;
      }

      case "charge.refunded": {
        const charge = event.data.object as Stripe.Charge;
        const dbSub = await prisma.subscription.findUnique({
          where: { stripeCustomerId: charge.customer as string },
        });

        if (dbSub) {
          // Rule #5: Handle refunds -> CANCELED
          await prisma.subscription.update({
            where: { id: dbSub.id },
            data: { status: "CANCELED" },
          });
          console.log(`[Webhook] Charge refunded for tenant ${dbSub.tenantId}. Subscription revoked.`);
        }
        break;
      }

      default:
        console.log(`[Webhook] Unhandled event type ${event.type}`);
    }

    // Mark event as processed
    await prisma.stripeEvent.update({
      where: { id: auditLog.id },
      data: { status: "PROCESSED", processedAt: new Date() },
    });

  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : "Processing failed";
    console.error(`[Webhook] Error processing ${event.type}:`, errorMessage);

    await prisma.stripeEvent.update({
      where: { id: auditLog.id },
      data: { status: "FAILED", error: errorMessage },
    });

    return NextResponse.json(
      { error: "Webhook handling failed" },
      { status: 500 },
    );
  }

  return NextResponse.json({ received: true });
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { recordActivity } from "@/lib/activity-log";
import { prisma } from "@/lib/prisma";
import { checkBotLimit } from "@/lib/subscription";
import { z } from "zod";

export const dynamic = "force-dynamic";

const createBotSchema = z.object({
  name: z.string().min(1),
  channel: z.enum(["web", "facebook", "telegram", "whatsapp"]).optional(),
  context: z.string().optional(),
  entryFlow: z.string().optional(),
});

export async function GET() {
  const session = await getServerSession(authOptions);
  if (!session?.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const bots = await prisma.bot.findMany({
      where: {
        tenantId: session.user.tenantId,
      },
      orderBy: { createdAt: "desc" },
      include: {
        channels: {
          select: {
            id: true,
            type: true,
            name: true,
            enabled: true,
            isActive: true,
          },
          orderBy: { createdAt: "asc" },
        },
      },
    });

    const mappedBots = bots.map((bot) => ({
      id: bot.id,
      name: bot.name,
      status: bot.enabled,
      createdAt: bot.createdAt,
      primaryChannel: bot.channels[0]?.type || "web",
      channels: bot.channels,
    }));

    // Mock project structure to satisfy frontend expected interface
    const projects = [
      {
        id: "default",
        name: "My Bots",
        bots: mappedBots,
      },
    ];

    return NextResponse.json({ projects });
  } catch {
    return NextResponse.json(
      { error: "Failed to fetch bots" },
      { status: 500 },
    );
  }
}

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions);
  if (!session?.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  // 1. Check Limits
  const limitStatus = await checkBotLimit(session.user.tenantId);
  if (!limitStatus.allowed) {
    return NextResponse.json(
      {
        error: "Plan limit reached",
        details: `You have reached the maximum of ${limitStatus.limit} bots on the ${limitStatus.planName} plan. Please upgrade.`,
      },
      { status: 403 },
    );
  }

  try {
    const body = await req.json();
    const parsed = createBotSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { error: "Invalid input", details: parsed.error.issues },
        { status: 400 },
      );
    }

    const { name, channel, context } = parsed.data;
    const normalizedChannelType = channel || "web";
    let parsedContext: any = {};
    if (context && context.trim()) {
      try {
        parsedContext = JSON.parse(context);
      } catch {
        parsedContext = context; // fallback to plain text if not valid JSON
      }
    }
    const bot = await prisma.bot.create({
      data: {
        name,
        tenantId: session.user.tenantId,
        enabled: true,
        context: parsedContext,
        entryFlow: parsed.data.entryFlow,
        channels: {
          create: {
            type: normalizedChannelType,
            name: "Default Channel",
            channelId: normalizedChannelType === "web" ? null : "default",
            enabled: true,
          },
        },
      },
    });

    await recordActivity({
      tenantId: session.user.tenantId,
      userId: typeof session.user.id === "string" ? session.user.id : undefined,
      type: "bot_created",
      title: "Bot Created",
      description: `Created bot ${bot.name}`,
      entityType: "bot",
      entityId: bot.id,
    });

    return NextResponse.json({ bot });
  } catch (error) {
    console.error("Bot creation error", error);
    return NextResponse.json(
      { error: "Failed to create bot" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { z } from "zod";
