import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { DataDeletionStatus } from "@prisma/client";
import { recordActivity } from "@/lib/activity-log";

export const dynamic = "force-dynamic";

/**
 * CRON: Process pending data deletion requests
 * This should be called periodically (e.g., daily) to fulfill Meta's requirements.
 */
export async function GET(req: Request) {
  // Simple auth check using a cron secret
  const authHeader = req.headers.get("authorization");
  if (
    process.env.CRON_SECRET &&
    authHeader !== `Bearer ${process.env.CRON_SECRET}`
  ) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    // 1. Alert for stuck/failed requests
    await checkAndAlertStuckRequests();

    const pendingRequests = await prisma.dataDeletionRequest.findMany({
      where: {
        status: DataDeletionStatus.PENDING,
      },
      take: 10, // Process in small batches
    });

    const results = [];

    for (const request of pendingRequests) {
      try {
        await prisma.dataDeletionRequest.update({
          where: { id: request.id },
          data: { status: DataDeletionStatus.IN_PROGRESS },
        });

        // If we have a tenantId, we can do a thorough cleanup
        if (request.tenantId) {
          await cleanupTenantData(request.tenantId, request.userId);
        } else if (request.email && request.email.endsWith("@facebook-user")) {
          // If it's a specific Facebook user deletion request without a tenantId yet,
          // we should look for contacts with this Facebook PSID and scrub them.
          const psid = request.email.split("@")[0];
          await cleanupFacebookUserData(psid);
        }

        await prisma.dataDeletionRequest.update({
          where: { id: request.id },
          data: {
            status: DataDeletionStatus.COMPLETED,
            processedAt: new Date(),
          },
        });

        // Audit log
        if (request.tenantId) {
          await recordActivity({
            tenantId: request.tenantId,
            userId: request.userId,
            type: "settings_updated",
            title: "Data Deletion Completed",
            description: `Facebook data deletion request ${request.confirmationCode} has been processed.`,
            metadata: {
              requestId: request.id,
              confirmationCode: request.confirmationCode,
              email: request.email,
            },
          });
        }

        results.push({ id: request.id, status: "success" });
      } catch (error) {
        console.error(`Failed to process deletion request ${request.id}:`, error);
        await prisma.dataDeletionRequest.update({
          where: { id: request.id },
          data: {
            status: DataDeletionStatus.ERROR,
            notes: `Error: ${error instanceof Error ? error.message : "Unknown error"}`,
          },
        });
        results.push({ id: request.id, status: "failed", error });
      }
    }

    return NextResponse.json({
      processed: pendingRequests.length,
      results,
    });
  } catch (error) {
    console.error("[Cron: Process Data Deletions] Error:", error);
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 },
    );
  }
}

/**
 * Checks for requests that are stuck in PENDING for > 24h or have failed notes
 */
async function checkAndAlertStuckRequests() {
  const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);

  const stuckRequests = await prisma.dataDeletionRequest.findMany({
    where: {
      OR: [
        {
          status: DataDeletionStatus.PENDING,
          requestedAt: { lt: twentyFourHoursAgo },
        },
        {
          status: DataDeletionStatus.ERROR,
        },
      ],
    },
    take: 5,
  });

  for (const request of stuckRequests) {
    console.warn(`Alert: Data deletion request ${request.id} is stuck or failed:`, request);

    // Log a system event for admin visibility
    // We use a generic system tenant ID or the request's tenantId if available
    const alertTenantId = request.tenantId || "system";

    await recordActivity({
      tenantId: alertTenantId,
      type: "system_event",
      title: "Data Deletion Alert",
      description: `Request ${request.confirmationCode} for ${request.email} is stuck or failed. Manual intervention may be required.`,
      metadata: {
        requestId: request.id,
        status: request.status,
        requestedAt: request.requestedAt,
        notes: request.notes,
      },
    });
  }
}

/**
 * Performs deep cleanup for a tenant (similar to scripts/cleanup_facebook_data.py)
 */
async function cleanupTenantData(tenantId: string, userId?: string | null) {
  const pages = await prisma.facebookPage.findMany({
    where: { tenantId },
    select: { id: true },
  });
  const pageIds = pages.map((p) => p.id);

  const operations: any[] = [
    // Delete flow assignments
    prisma.flowAssignment.deleteMany({
      where: { pageId: { in: pageIds } },
    }),
    // Delete flow sessions
    prisma.flowSession.deleteMany({
      where: { pageId: { in: pageIds } },
    }),
    // Delete onboarding sessions
    prisma.onboardingSession.deleteMany({
      where: { facebookPageId: { in: pageIds } },
    }),
    // Delete leads
    prisma.lead.deleteMany({
      where: { pageId: { in: pageIds } },
    }),
    // Unlink conversations
    prisma.crmConversation.updateMany({
      where: { facebookPageId: { in: pageIds } },
      data: { facebookPageId: null },
    }),
    // Delete the pages
    prisma.facebookPage.deleteMany({
      where: { id: { in: pageIds } },
    }),
    // Remove Facebook channels from bots
    prisma.channel.deleteMany({
      where: {
        type: "facebook",
        bot: { tenantId },
      },
    }),
    // Reset channel status
    prisma.tenantChannelStatus.updateMany({
      where: { tenantId },
      data: { facebook: false },
    }),
  ];

  // If we have a userId, we should also remove their Facebook account connection
  if (userId) {
    operations.push(
      prisma.account.deleteMany({
        where: {
          userId,
          provider: "facebook",
        },
      }),
    );
  }

  await prisma.$transaction(operations);
}

/**
 * Scrubs a specific Facebook user's data across the system
 */
async function cleanupFacebookUserData(psid: string) {
  // Find all contact identities for this PSID
  const identities = await prisma.contactIdentity.findMany({
    where: {
      type: "facebook_psid",
      value: psid,
    },
  });

  const contactIds = identities.map((i) => i.contactId);

  if (contactIds.length > 0) {
    // Meta's "Data Deletion" requires complete removal of data received from them.
    const conversations = await prisma.crmConversation.findMany({
      where: { contactId: { in: contactIds } },
      select: { id: true },
    });
    const conversationIds = conversations.map((c) => c.id);

    await prisma.$transaction([
      prisma.crmMessage.deleteMany({
        where: { conversationId: { in: conversationIds } },
      }),
      prisma.internalNote.deleteMany({
        where: { conversationId: { in: conversationIds } },
      }),
      prisma.lead.deleteMany({
        where: { contactId: { in: contactIds } },
      }),
      prisma.onboardingSession.deleteMany({
        where: { contactId: { in: contactIds } },
      }),
      prisma.flowSession.deleteMany({
        where: { userId: psid },
      }),
      prisma.crmConversation.deleteMany({
        where: { contactId: { in: contactIds } },
      }),
      prisma.contactIdentity.deleteMany({
        where: { contactId: { in: contactIds } },
      }),
      prisma.contact.deleteMany({
        where: { id: { in: contactIds } },
      }),
    ]);
  } else {
    // Also catch any FlowSessions that might not be linked to a contact yet
    await prisma.flowSession.deleteMany({
      where: { userId: psid },
    });
  }
}

import { summarizeOnboardingData, customizeFlowNodesWithAI, appendLeadGenerationNodes } from "@/lib/onboarding-ai";
import { getTemplateByCategory, FlowTemplateCategory } from "@/lib/flow-templates";
import { withAuthAndTenant } from "@/lib/route-helpers";
import { OnboardingSchema, OnboardingData, OnboardingSummary } from "@/types/shared/onboarding";
import { successResponse, errorResponse, validationErrorResponse } from "@/lib/api-response";
import { Prisma } from "@prisma/client";

// Schema is now in types/shared/onboarding.ts

export const GET = withAuthAndTenant(async ({ tenantId }, request, context, db) => {
  const tenant = await db.tenant.findUnique({
    where: { id: tenantId },
    select: {
      isOnboarded: true,
      onboardingStep: true,
      onboardingData: true,
    },
  });

  return successResponse(tenant);
});

export const PATCH = withAuthAndTenant(async ({ tenantId }, request, context, db) => {
  try {
    const body = await request.json();
    const { step, data } = body;

    const currentTenant = await db.tenant.findUnique({
      where: { id: tenantId },
      select: { onboardingData: true },
    });

    const currentData = (currentTenant?.onboardingData as Record<string, unknown>) || {};
    const newData = { ...currentData, ...data };

    await db.tenant.update({
      where: { id: tenantId },
      data: {
        onboardingStep: step,
        onboardingData: newData as Prisma.InputJsonValue,
      },
    });

    return successResponse({ success: true });
  } catch (error) {
    console.error("[Onboarding PATCH] Error:", error);
    return errorResponse("Failed to update onboarding progress");
  }
});

export const POST = withAuthAndTenant(async ({ id, tenantId }, request, context, db) => {
  try {
    const body = await request.json();
    const validatedData = OnboardingSchema.parse(body);

    let summary: OnboardingSummary;
    try {
      summary = await summarizeOnboardingData(validatedData);
    } catch (err) {
      console.error("[Onboarding AI] Failed to summarize data", err);
      summary = {
        companyProfile: `${validatedData.kyc.company} is a business in the ${validatedData.businessBasics.industry} industry.`,
        targetAudience: Array.isArray(validatedData.productDetails.targetCustomers)
          ? validatedData.productDetails.targetCustomers.join(", ")
          : validatedData.productDetails.targetCustomers,
        keyOfferings: validatedData.productSpecifics.mainProducts,
        pricingStrategy: validatedData.productSpecifics.pricing,
        competitiveAdvantage: validatedData.productSpecifics.usps,
        commonQueries: "Refer to support documents.",
        toneAndVoice: "Professional and helpful",
        isPlaceholder: true
      };
    }

    const mapIndustryToCategory = (industry: string): FlowTemplateCategory => {
      const lower = industry.toLowerCase();
      if (lower.includes("saas")) return "saas";
      if (lower.includes("e-commerce") || lower.includes("retail")) return "ecommerce";
      if (lower.includes("agency")) return "agencies";
      if (lower.includes("real estate")) return "real-estate";
      if (lower.includes("fitness") || lower.includes("gym")) return "boutique-gym";
      if (lower.includes("beauty") || lower.includes("salon")) return "hair-salon";
      if (lower.includes("restaurant") || lower.includes("food")) return "restaurant";
      if (lower.includes("hotel") || lower.includes("hospitality")) return "hotel";
      if (lower.includes("service")) return "services";
      return "welcome";
    };

    const category = mapIndustryToCategory(validatedData.businessBasics.industry);
    const template = getTemplateByCategory(category) || getTemplateByCategory("welcome")!;

    const customizedNodesRaw = await customizeFlowNodesWithAI(template.nodes, summary);
    const customizedNodes = appendLeadGenerationNodes(customizedNodesRaw);

    const flow = await db.flow.create({
      data: {
        name: `${validatedData.kyc.company} Main Flow`,
        description: `Automated flow generated during onboarding from ${template.name} template`,
        tenantId,
        ownerId: id,
        isGlobal: false,
        isActive: true,
        version: 1,
        language: "en",
        fallbackMessage: summary.isPlaceholder ? "Sorry, I didn't understand that." : `I'm not quite sure about that. Our ${validatedData.businessBasics.industry} team will get back to you soon.`,
        maxTimeout: 300,
        nodes: {
          create: customizedNodes.map(
            (node) =>
              ({
                type: node.type,
                content: node.content as Prisma.InputJsonValue,
                order: node.order,
              }) as Prisma.FlowNodeCreateWithoutFlowInput,
          ),
        },
      },
    });

    await db.tenant.update({
      where: { id: tenantId },
      data: {
        isOnboarded: true,
        onboardingData: {
          raw: validatedData,
          summary: summary,
        } as unknown as Prisma.InputJsonValue,
      },
    });

    const botCount = await db.bot.count({ where: { tenantId } });
    if (botCount === 0) {
      await db.bot.create({
        data: {
          name: `${validatedData.kyc.company} AI Assistant`,
          tenantId,
          enabled: true,
          context: summary as unknown as Prisma.InputJsonValue,
          entryFlow: flow.id,
        },
      });
    } else {
      await db.bot.updateMany({
        where: { tenantId },
        data: {
          context: summary as unknown as Prisma.InputJsonValue,
          entryFlow: flow.id,
        },
      });
    }

    return successResponse({ success: true, summary, flowId: flow.id });
  } catch (error) {
    if (error instanceof Error && "name" in error && error.name === "ZodError") {
       return validationErrorResponse(error as any);
    }
    console.error("[Onboarding POST] Error:", error);
    return errorResponse("Failed to complete onboarding");
  }
});

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.tenantId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const tenant = await prisma.tenant.findUnique({
      where: { id: session.user.tenantId },
      select: { aiProvider: true, aiApiKey: true, aiModel: true },
    });

    return NextResponse.json({
      aiProvider: tenant?.aiProvider || "default",
      aiModel: tenant?.aiModel,
      hasApiKey: !!tenant?.aiApiKey,
    });
  } catch (error) {
    console.error("[AI Settings GET] Error:", error);
    return NextResponse.json({ error: "Failed to fetch AI settings" }, { status: 500 });
  }
}

export async function PATCH(req: NextRequest) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.tenantId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const { aiProvider, aiApiKey, aiModel } = body;

    // Validate provider
    const validProviders = ["default", "gemini", "openai", "anthropic"];
    if (!validProviders.includes(aiProvider)) {
      return NextResponse.json(
        { error: "Invalid AI provider" },
        { status: 400 },
      );
    }

    // Validate model based on provider
    const validModels: Record<string, string[]> = {
      openai: ["gpt-4o", "gpt-4o-mini"],
      anthropic: ["claude-3-5-sonnet-latest", "claude-3-haiku-latest"],
      gemini: ["gemini-1.5-pro", "gemini-1.5-flash"],
      default: [],
    };

    if (
      aiProvider !== "default" &&
      aiModel &&
      !validModels[aiProvider]?.includes(aiModel)
    ) {
      return NextResponse.json({ error: "Invalid AI model" }, { status: 400 });
    }

    const data: any = {
      aiProvider,
      aiModel: aiProvider === "default" ? null : aiModel || null,
    };

    if (aiProvider === "default") {
      data.aiApiKey = null;
    } else if (aiApiKey !== undefined && aiApiKey !== "********") {
      data.aiApiKey = aiApiKey === "" ? null : aiApiKey;
    }

    const updatedTenant = await prisma.tenant.update({
      where: { id: session.user.tenantId },
      data,
    });

    return NextResponse.json({
      aiProvider: updatedTenant.aiProvider,
      message: "AI settings updated successfully",
    });
  } catch (error) {
    console.error("[AI Settings PATCH] Error:", error);
    return NextResponse.json({ error: "Failed to update AI settings" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { exportTenantData } from "@/lib/data-export";
import { prisma } from "@/lib/prisma";
import { isPlatformAdmin } from "@/lib/admin";

export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id || !session.user.tenantId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const type = req.nextUrl.searchParams.get("type");

    if (type === "onboarding") {
      if (!isPlatformAdmin(session)) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
      }

      const tenants = await prisma.tenant.findMany({
        include: {
          users: { select: { email: true, name: true } },
          subscriptions: { include: { plan: true } },
        },
        orderBy: {
          createdAt: "desc",
        },
      });

      // Construct CSV
      let csv = "Tenant Name,Email,Company,Industry,Stage,Status,Plan,Created At\n";
      tenants.forEach(t => {
        const data = t.onboardingData as any;
        const email = t.users[0]?.email || "";
        const companyName = data?.raw?.kyc?.company || "";
        const industry = data?.raw?.businessBasics?.industry || "";
        const stage = t.isOnboarded ? "COMPLETED" : t.onboardingStep.toString();
        const status = t.isOnboarded ? "COMPLETED" : t.onboardingStep > 0 ? "IN_PROGRESS" : "NOT_STARTED";
        // Handle subscriptions array to match schema
        const plan = t.subscriptions && Array.isArray(t.subscriptions) ? t.subscriptions[0]?.plan?.displayName || "" : "";
        const createdAt = new Date(t.createdAt).toISOString();

        csv += `"${t.name}","${email}","${companyName}","${industry}","${stage}","${status}","${plan}","${createdAt}"\n`;
      });

      return new NextResponse(csv, {
        status: 200,
        headers: {
          "Content-Type": "text/csv",
          "Content-Disposition": `attachment; filename="onboarding-export-${new Date().toISOString().split('T')[0]}.csv"`,
        },
      });
    }

    // Only allow admins or the account owner to export data
    // In this multi-tenant setup, any user with the correct tenantId can export their workspace data
    // but typically we'd want to restrict this to the tenant admin.

    const exportData = await exportTenantData(session.user.tenantId);

    return new NextResponse(JSON.stringify(exportData, null, 2), {
      status: 200,
      headers: {
        "Content-Type": "application/json",
        "Content-Disposition": `attachment; filename="replybase-data-export-${session.user.tenantId}-${new Date().toISOString().split('T')[0]}.json"`,
      },
    });
  } catch (error) {
    console.error("[Data Export API] Error:", error);
    return NextResponse.json(
      { error: "Failed to generate data export" },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { ModelMessage } from "ai";

import { prisma } from "@/lib/prisma";
import {
  createWebchatCorsHeaders,
  getWebchatOriginRejectionReason,
  isWebchatOriginAllowed,
} from "@/lib/webchat-cors";
import { findActiveWebChannel } from "@/lib/webchat";
import { verifyWebchatSessionToken } from "@/lib/webchat-session";

// 2. Atomic Idempotency Check: Prevent concurrent duplicates
const processingLocks = new Set<string>();

export async function POST(request: NextRequest) {
  if (!isWebchatOriginAllowed(request)) {
    const reason = getWebchatOriginRejectionReason(request);
    console.error("[Webchat Message] Blocked by CORS", {
      origin: request.headers.get("origin"),
      referer: request.headers.get("referer"),
      reason,
    });
    return NextResponse.json(
      { error: "Origin not allowed", reason },
      { status: 403, headers: createWebchatCorsHeaders(request) },
    );
  }

  const body = await request.json();
  const { token, conversationId, botId, message, planName } = body;
  const lockKey = `${conversationId}:${String(message || "").trim()}`;

  try {
    console.log("[Webchat Message] Incoming request", body);

    // 1. Verify session token
    let session;
    try {
      session = verifyWebchatSessionToken(token);
    } catch (err) {
      console.error("[Webchat Message] Invalid token", { error: err });
      return NextResponse.json(
        { error: "Invalid session" },
        { status: 401, headers: createWebchatCorsHeaders(request) },
      );
    }

    const { tenantId } = session;

    // Defensive: require all fields
    if (!conversationId || !botId || !message || !planName) {
      console.error("[Webchat Message] Missing required fields", {
        conversationId,
        botId,
        message,
        planName,
      });
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400, headers: createWebchatCorsHeaders(request) },
      );
    }

    if (processingLocks.has(lockKey)) {
      console.warn("[Webchat Message] Concurrent duplicate blocked", { conversationId });
      return NextResponse.json(
        { status: "duplicate_ignored" },
        { status: 200, headers: createWebchatCorsHeaders(request) }
      );
    }
    processingLocks.add(lockKey);

    // Save inbound message first
    await prisma.crmMessage.create({
      data: {
        tenantId,
        conversationId,
        direction: "inbound",
        content: message.trim(),
        source: "human",
      },
    });

    const channel = await findActiveWebChannel({ botId });
    if (!channel) {
      console.error("[Webchat Message] Channel not found", { botId });
      return NextResponse.json(
        { error: "Channel not found" },
        { status: 404, headers: createWebchatCorsHeaders(request) },
      );
    }

    const config = (channel.config || {}) as Record<string, any>;
    const fallbackMode = config.fallbackMode || "ai";
    const customFallbackMessage =
      config.customFallbackMessage ||
      "All of our agents are currently busy or offline. Please leave your email address, and we'll get back to you as soon as possible.";

    if (fallbackMode === "manual") {
      console.warn("[Webchat Message] Manual fallback mode active", {
        conversationId,
        botId,
      });
      await prisma.crmMessage.create({
        data: {
          tenantId,
          conversationId,
          direction: "outbound",
          content: customFallbackMessage,
          source: "manual_fallback",
        },
      });
      return NextResponse.json(
        {
          responses: [
            {
              type: "text",
              text: customFallbackMessage,
            },
          ],
          meta: { mode: "manual_fallback" },
        },
        { headers: createWebchatCorsHeaders(request) }
      );
    }

    const conversation = await prisma.crmConversation.findUnique({
      where: { id: conversationId },
      select: { contactId: true, metadata: true },
    });

    if (!conversation) {
      return NextResponse.json(
        { error: "Conversation not found" },
        { status: 404, headers: createWebchatCorsHeaders(request) },
      );
    }

    // Try executing assigned flow first natively
    const { buildWebchatSourceContext, executeWebchatFlowFirst } = await import(
      "@/lib/webchat-conversation-engine"
    );

    const sourceContext = buildWebchatSourceContext({
      requestOrigin: request.headers.get("origin"),
      requestReferer: request.headers.get("referer"),
      messageMetadata: body.metadata as Record<string, unknown> | undefined,
      existingMetadata: conversation.metadata as Record<string, unknown> | undefined,
    });

    const flowResult = await executeWebchatFlowFirst({
      tenantId: channel.bot.tenantId,
      botId,
      contactId: conversation.contactId,
      siteId: String((conversation.metadata as Record<string, any>)?.siteId || channel.id),
      message,
      channelId: channel.id,
      sourceContext,
    });

    if (flowResult && flowResult.handled) {
      if (flowResult.responses.length > 0) {
        const outMessages = flowResult.responses
          .filter((r) => r.type === "text")
          .map((r) => (r as { type: "text"; text: string }).text);

        await prisma.crmMessage.createMany({
          data: outMessages.map((outMsg) => ({
            tenantId,
            conversationId,
            direction: "outbound",
            content: outMsg,
            source: "flow",
          })),
        });

        console.log("[Webchat Message] Responding from flow", {
          responses: flowResult.responses,
        });
      }

      return NextResponse.json(
        {
          responses: flowResult.responses,
          meta: { mode: "flow", flowId: flowResult.flowId },
        },
        { headers: createWebchatCorsHeaders(request) },
      );
    }

    // fallbackMode is "ai" or missing AND Flow bypassed: run AI, fallback to customFallbackMessage if AI fails
    // Fetch last messages for context

    const lastMessages = await prisma.crmMessage.findMany({
      where: { conversationId },
      orderBy: { createdAt: "desc" },
      take: 10,
      select: { content: true, source: true },
    });
    const aiMessages: ModelMessage[] = lastMessages.reverse().map((msg) => ({
      role: msg.source === "human" ? "user" : "assistant",
      content: msg.content,
    }));
    // Note: We already saved the current message, so it's likely already in lastMessages.
    // However, findMany might be slightly delayed or we might have fetched before save.
    // To be safe and consistent with the existing logic, we ensure the current message is the last one.
    if (aiMessages.length === 0 || aiMessages[aiMessages.length - 1].content !== message) {
       aiMessages.push({ role: "user", content: message });
    }

    // Dynamically import aiFallback to avoid circular deps
    const { aiFallback } = await import("@/lib/ai-fallback");
    let aiText = "";
    let aiErrorOccurred = false;
    try {
      const aiStream = await aiFallback({
        botId,
        conversationId,
        messages: aiMessages,
        planName,
      });
      aiText =
        aiStream && "text" in aiStream
          ? await aiStream.text
          : String(aiStream ?? "");
    } catch (aiError) {
      aiErrorOccurred = true;
      const isQuotaError = String(aiError).includes("RESOURCE_EXHAUSTED") || String(aiError).includes("429");
      const isTimeout = String(aiError).toLowerCase().includes("timeout") || String(aiError).toLowerCase().includes("abort");

      aiText = isQuotaError 
        ? "I'm experiencing high demand right now. I've notified the team, but in the meantime, I'll be using my standard responses." 
        : isTimeout
          ? "I'm taking a bit longer than usual to think. Please bear with me or try again in a moment."
          : customFallbackMessage;

      console.error("[Webchat Message] AI error, using fallback", {
        error: aiError,
        isQuotaError,
        isTimeout
      });
    }

    if (aiText.trim()) {
      await prisma.crmMessage.create({
        data: {
          tenantId,
          conversationId,
          direction: "outbound",
          content: aiText.trim(),
          source: aiErrorOccurred ? "manual_fallback" : "ai",
        },
      });
      console.log("[Webchat Message] Responding", {
        mode: aiErrorOccurred ? "manual_fallback" : "ai_fallback",
        aiText,
      });
      return NextResponse.json(
        {
          responses: [
            {
              type: "text",
              text: aiText.trim(),
            },
          ],
          meta: { mode: aiErrorOccurred ? "manual_fallback" : "ai_fallback" },
        },
        { headers: createWebchatCorsHeaders(request) }
      );
    }

    // Static fallback if all else fails
    console.error(
      "[Webchat Message] All fallbacks failed, using static fallback",
      { conversationId, botId },
    );
    return NextResponse.json(
      {
        responses: [
          {
            type: "text",
            text: customFallbackMessage,
          },
        ],
        meta: { mode: "safe_fallback" },
      },
      { headers: createWebchatCorsHeaders(request) }
    );
  } catch (error) {
    console.error("[Webchat Message] Internal server error", { error });
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500, headers: createWebchatCorsHeaders(request) },
    );
  } finally {
    processingLocks.delete(lockKey);
  }
}

export async function OPTIONS(request: NextRequest) {
  if (!isWebchatOriginAllowed(request)) {
    const reason = getWebchatOriginRejectionReason(request);
    return NextResponse.json(
      { error: "Origin not allowed", reason },
      {
        status: 403,
        headers: createWebchatCorsHeaders(request),
      },
    );
  }

  return new NextResponse(null, {
    status: 204,
    headers: createWebchatCorsHeaders(request),
  });
}

