               <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm font-medium text-gray-600">Rate Limits</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-3xl font-bold">{snapshot.reasonCounts.rateLimit}</div>
