"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { MoreHorizontal, Trash2, Copy, MessageSquare } from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useConfirmation } from "@/components/ui/confirmation-provider";
import { DataTable } from "@/components/data-table";
import { ColumnDef, PaginationState, RowSelectionState } from "@tanstack/react-table";
import { Checkbox } from "@/components/ui/checkbox";

type ConversationListItem = {
  id: string;
  channel: string;
  updatedAt: string;
  contact: {
    id: string;
    name: string | null;
  };
};

const activityDateFormatter = new Intl.DateTimeFormat("en-GB", {
  day: "2-digit",
  month: "2-digit",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
});

function formatActivityDate(value: string): string {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return "-";
  return activityDateFormatter.format(parsed);
}

export function ConversationsList() {
  const router = useRouter();
  const { confirm } = useConfirmation();
  const [conversations, setConversations] = useState<ConversationListItem[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [pageCount, setPageCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 20,
  });
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({});
  const [isAllMatchingSelected, setIsAllMatchingSelected] = useState(false);

  const fetchConversations = useCallback(async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page: (pagination.pageIndex + 1).toString(),
        limit: pagination.pageSize.toString(),
      });
      const response = await fetch(`/api/conversations?${params.toString()}`);
      if (response.ok) {
        const result = await response.json();
        const data = result.data || [];
        const metadata = result.metadata || {};

        setConversations(data);
        setTotalCount(metadata.totalCount || 0);
        setPageCount(metadata.totalPages || 0);
        setIsAllMatchingSelected(false);
      }
    } catch (error) {
      console.error("Failed to fetch conversations:", error);
      toast.error("Failed to load conversations");
    } finally {
      setLoading(false);
    }
  }, [pagination]);

  useEffect(() => {
    fetchConversations();
  }, [fetchConversations]);

  const handleCopyConversationId = async (conversationId: string) => {
    try {
      await navigator.clipboard.writeText(conversationId);
      toast.success("Conversation ID copied");
    } catch {
      toast.error("Failed to copy conversation ID");
    }
  };

  const handleDeleteConversations = async (ids: string[], allMatching = false) => {
    const message = allMatching
      ? `Are you sure you want to delete ALL ${totalCount} matching conversations? This cannot be undone.`
      : `Are you sure you want to delete ${ids.length} conversation(s)? This cannot be undone.`;

    const confirmed = await confirm({
      title: "Delete Conversations",
      description: message,
      confirmText: "Delete",
      variant: "destructive",
    });

    if (!confirmed) return;

    try {
      const response = await fetch("/api/conversations", {
        method: "DELETE",
        body: JSON.stringify({ ids: allMatching ? "ALL" : ids }),
      });

      if (!response.ok) throw new Error("Failed to delete conversations");

      toast.success(`${ids.length} conversation(s) deleted`);
      setRowSelection({});
      fetchConversations();
      router.refresh();
    } catch (error) {
      toast.error("Failed to delete conversations");
    }
  };

  const columns = useMemo<ColumnDef<ConversationListItem>[]>(() => [
    {
      id: "select",
      header: ({ table }) => (
        <Checkbox
          checked={table.getIsAllPageRowsSelected()}
          onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
          aria-label="Select all"
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(value) => row.toggleSelected(!!value)}
          aria-label="Select row"
        />
      ),
      enableSorting: false,
      enableHiding: false,
    },
    {
      accessorKey: "contact.name",
      header: "Contact",
      cell: ({ row }) => {
        const name = row.original.contact.name || "Unknown contact";
        return (
          <div className="flex items-center gap-3">
            <Avatar className="h-8 w-8">
              <AvatarFallback>{name.charAt(0) || "?"}</AvatarFallback>
            </Avatar>
            <span className="font-medium">{name}</span>
          </div>
        );
      },
    },
    {
      accessorKey: "channel",
      header: "Channel",
      cell: ({ row }) => <Badge variant="outline">{row.original.channel}</Badge>,
    },
    {
      accessorKey: "updatedAt",
      header: "Last Activity",
      cell: ({ row }) => formatActivityDate(row.original.updatedAt),
    },
    {
      id: "actions",
      header: () => <div className="text-right">Actions</div>,
      enableHiding: false,
      cell: ({ row }) => (
        <div className="text-right">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon">
                <MoreHorizontal className="h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem asChild>
                <Link href={`/conversations/${row.original.id}`}>
                  <MessageSquare className="mr-2 h-4 w-4" />
                  Open chat
                </Link>
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => handleCopyConversationId(row.original.id)}>
                <Copy className="mr-2 h-4 w-4" />
                Copy ID
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => handleDeleteConversations([row.original.id])}
                className="text-destructive"
              >
                <Trash2 className="mr-2 h-4 w-4" />
                Delete
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      ),
    },
  ], []);

  const selectedIds = useMemo(() => Object.keys(rowSelection), [rowSelection]);
  const currentSelectionCount = isAllMatchingSelected ? totalCount : selectedIds.length;

  return (
    <div className="space-y-4">
      {selectedIds.length > 0 && (
        <div className="flex justify-end gap-2">
          <Button variant="destructive" size="sm" onClick={() => handleDeleteConversations(selectedIds, isAllMatchingSelected)}>
            <Trash2 className="mr-2 h-4 w-4" />
            Delete ({currentSelectionCount})
          </Button>
        </div>
      )}
      <DataTable
        columns={columns}
        data={conversations}
        pageCount={pageCount}
        pagination={pagination}
        onPaginationChange={setPagination}
        rowSelection={rowSelection}
        onRowSelectionChange={setRowSelection}
        isLoading={loading}
        persistenceKey="conversations_table"
        totalCount={totalCount}
        onSelectAllMatching={setIsAllMatchingSelected}
        isAllMatchingSelected={isAllMatchingSelected}
      />
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import {
  CrmConversation,
  CrmMessage,
  InternalNote,
  User,
  Contact,
} from "@prisma/client";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

type MessageWithAuthor = CrmMessage & { author?: Partial<User> };
type NoteWithAuthor = InternalNote & { author: Partial<User> };

type ConversationViewData = CrmConversation & {
  messages: MessageWithAuthor[];
  internalNotes: NoteWithAuthor[];
  contact: Contact;
};

export function MessageFeed({
  conversation,
}: {
  conversation: ConversationViewData;
}) {
  const bottomRef = useRef<HTMLDivElement>(null);

  const combinedFeed = [
    ...conversation.messages,
    ...conversation.internalNotes,
  ].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
  );

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [combinedFeed.length]);

  return (
    <div className="min-h-0 flex-1 overflow-y-auto p-4 space-y-4">
      {combinedFeed.map((item) =>
        "direction" in item ? (
          <Message
            key={item.id}
            message={item}
            contact={conversation.contact}
          />
        ) : (
          <Note key={item.id} note={item} />
        )
      )}
      <div ref={bottomRef} />
    </div>
  );
}

function Message({
  message,
  contact,
}: {
  message: MessageWithAuthor;
  contact: { name: string | null };
}) {
  const isOutbound = message.direction === "outbound";
  const authorName = isOutbound ? "You" : contact.name || "Unknown";
  const authorImage = ""; // No image available

  return (
    <div
      className={`flex items-start gap-4 ${isOutbound ? "justify-end" : ""}`}
    >
      {!isOutbound && (
        <Avatar>
          <AvatarImage src={authorImage} />
          <AvatarFallback>{authorName.charAt(0)}</AvatarFallback>
        </Avatar>
      )}
      <div
        className={`rounded-lg p-3 ${
          isOutbound ? "bg-blue-500 text-white" : "bg-gray-200"
        }`}
      >
        <p className="text-sm">{message.content}</p>
      </div>
      {isOutbound && (
        <Avatar>
          <AvatarImage src={authorImage} />
          <AvatarFallback>Y</AvatarFallback>
        </Avatar>
      )}
    </div>
  );
}

function Note({ note }: { note: NoteWithAuthor }) {
  return (
    <div className="flex justify-center my-6">
      <div className="max-w-[80%] bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded shadow-sm relative">
        <div className="flex items-center gap-2 mb-1">
          <span className="text-[10px] font-bold text-yellow-700 uppercase tracking-wider">
            Internal Note
          </span>
          <span className="text-[10px] text-yellow-600">
            • {new Date(note.createdAt).toLocaleString()}
          </span>
        </div>
        <div className="text-sm text-yellow-900 italic leading-relaxed">
          "{note.content}"
        </div>
        <div className="mt-2 text-xs font-medium text-yellow-700 flex items-center gap-1">
          <Avatar className="w-4 h-4">
            <AvatarImage src={note.author.image ?? ""} />
            <AvatarFallback className="text-[8px] bg-yellow-200">
              {note.author.name?.charAt(0) ?? "U"}
            </AvatarFallback>
          </Avatar>
          {note.author.name || "Unknown Team Member"}
        </div>
      </div>
    </div>
  );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  CheckCircle2,
  AlertCircle,
  Activity,
  Clock,
  Bell,
  Radio,
} from "lucide-react";

interface StatusCardsProps {
  isAutomationReady: boolean;
  connectedChannelsCount: number;
  connectedLeadDestinationsCount: number;
  lastMessageTimestamp: Date | null;
}

function formatTimeAgo(date: Date): string {
  const seconds = Math.floor((new Date().getTime() - date.getTime()) / 1000);
  if (seconds < 60) return "just now";
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes} minute${minutes !== 1 ? "s" : ""} ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours} hour${hours !== 1 ? "s" : ""} ago`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days} day${days !== 1 ? "s" : ""} ago`;
  const weeks = Math.floor(days / 7);
  if (weeks < 4) return `${weeks} week${weeks !== 1 ? "s" : ""} ago`;
  const months = Math.floor(days / 30);
  return `${months} month${months !== 1 ? "s" : ""} ago`;
}

export function StatusCards({
  isAutomationReady,
  connectedChannelsCount,
  connectedLeadDestinationsCount,
  lastMessageTimestamp,
}: StatusCardsProps) {
  return (
    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
      {/* AI Status */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Automation</CardTitle>
          {isAutomationReady ? (
            <CheckCircle2 className="h-4 w-4 text-green-500" />
          ) : (
            <AlertCircle className="h-4 w-4 text-muted-foreground" />
          )}
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">
            {isAutomationReady ? "Ready" : "Pending"}
          </div>
          <p className="text-xs text-muted-foreground mt-1">
            {isAutomationReady
              ? "Lead capture channels are connected"
              : "Connect Webchat or Telegram to start receiving leads"}
          </p>
        </CardContent>
      </Card>

      {/* Connected Channels */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">
            Connected Channels
          </CardTitle>
          <Radio className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">{connectedChannelsCount}</div>
          <p className="text-xs text-muted-foreground mt-1">
            {connectedChannelsCount === 0
              ? "No channels connected"
              : `${connectedChannelsCount} channel${connectedChannelsCount !== 1 ? "s" : ""} live`}
          </p>
        </CardContent>
      </Card>

      {/* Engine Status removed: AI/engine is deprecated */}

      {/* Lead Destinations */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Lead Alerts</CardTitle>
          <Bell className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">
            {connectedLeadDestinationsCount}
          </div>
          <p className="text-xs text-muted-foreground mt-1">
            {connectedLeadDestinationsCount === 0
              ? "No email or Telegram alerts configured"
              : `${connectedLeadDestinationsCount} destination${connectedLeadDestinationsCount !== 1 ? "s" : ""} configured`}
          </p>
        </CardContent>
      </Card>

      {/* Last Activity */}
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Last Activity</CardTitle>
          <Clock className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="text-2xl font-bold">
            {lastMessageTimestamp ? formatTimeAgo(lastMessageTimestamp) : "—"}
          </div>
          <p className="text-xs text-muted-foreground mt-1">
            {lastMessageTimestamp
              ? "Most recent lead activity"
              : "No conversations yet"}
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  type ColumnDef,
  type Table as ReactTable,
  type OnChangeFn,
  type PaginationState,
  type RowSelectionState,
  type VisibilityState,
} from "@tanstack/react-table";
import {
  IconChevronDown,
  IconChevronLeft,
  IconChevronRight,
  IconChevronsLeft,
  IconChevronsRight,
  IconLayoutColumns,
  IconLoader,
} from "@tabler/icons-react";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
  pageCount: number;
  pagination: PaginationState;
  onPaginationChange: OnChangeFn<PaginationState>;
  rowSelection?: RowSelectionState;
  onRowSelectionChange?: OnChangeFn<RowSelectionState>;
  isLoading?: boolean;
  persistenceKey?: string;
  onRowClick?: (row: TData) => void;
  getRowId?: (row: TData) => string;
  totalCount?: number;
  onSelectAllMatching?: (isSelected: boolean) => void;
  isAllMatchingSelected?: boolean;
}

export function DataTable<TData, TValue>({
  columns,
  data,
  pageCount,
  pagination,
  onPaginationChange,
  rowSelection = {},
  onRowSelectionChange,
  isLoading = false,
  persistenceKey,
  onRowClick,
  getRowId,
  totalCount,
  onSelectAllMatching,
  isAllMatchingSelected = false,
}: DataTableProps<TData, TValue>) {
  const [focusedIndex, setFocusedIndex] = React.useState<number>(-1);
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>(
    () => {
      if (persistenceKey && typeof window !== "undefined") {
        const saved = localStorage.getItem(`datatable_visibility_${persistenceKey}`);
        if (saved) {
          try {
            return JSON.parse(saved);
          } catch (e) {
            console.error("Failed to parse column visibility", e);
          }
        }
      }
      return {};
    }
  );

  React.useEffect(() => {
    if (persistenceKey) {
      localStorage.setItem(
        `datatable_visibility_${persistenceKey}`,
        JSON.stringify(columnVisibility)
      );
    }
  }, [columnVisibility, persistenceKey]);

  const table = useReactTable({
    data,
    columns,
    pageCount,
    state: {
      pagination,
      rowSelection,
      columnVisibility,
    },
    onPaginationChange,
    onRowSelectionChange,
    onColumnVisibilityChange: setColumnVisibility,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    enableRowSelection: true,
    getRowId: getRowId || ((row: TData) => (row as { id?: string }).id || ""),
  });

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent) => {
      const rows = table.getRowModel().rows;
      if (!rows.length) return;

      if (e.key === "ArrowDown") {
        e.preventDefault();
        setFocusedIndex((prev) => Math.min(prev + 1, rows.length - 1));
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setFocusedIndex((prev) => Math.max(prev - 1, 0));
      } else if (e.key === "Enter" && focusedIndex >= 0) {
        e.preventDefault();
        const row = rows[focusedIndex];
        if (onRowClick) {
          onRowClick(row.original);
        } else {
          row.toggleSelected();
        }
      } else if (e.key === " ") {
        e.preventDefault();
        if (focusedIndex >= 0) {
          rows[focusedIndex].toggleSelected();
        }
      }
    },
    [table, focusedIndex, onRowClick]
  );

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex-1 text-sm text-muted-foreground">
          {table.getFilteredSelectedRowModel()?.rows?.length ?? 0} of{" "}
          {table.getFilteredRowModel()?.rows?.length ?? 0} row(s) selected.
        </div>
        <div className="flex items-center gap-2">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm" className="ml-auto">
                <IconLayoutColumns className="mr-2 h-4 w-4" />
                Columns
                <IconChevronDown className="ml-2 h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56">
              {table
                .getAllColumns()
                .filter((column) => column.getCanHide())
                .map((column) => {
                  const header = column.columnDef.header;
                  const label = typeof header === "string"
                    ? header
                    : typeof header === "function"
                      ? column.id
                      : column.id;

                  return (
                    <DropdownMenuCheckboxItem
                      key={column.id}
                      className="capitalize"
                      checked={column.getIsVisible()}
                      onCheckedChange={(value) =>
                        column.toggleVisibility(!!value)
                      }
                    >
                      {label}
                    </DropdownMenuCheckboxItem>
                  );
                })}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
      {Object.keys(rowSelection).length > 0 && totalCount && onSelectAllMatching && (
        <div className="bg-muted/50 border rounded-md p-2 text-center text-sm mb-4">
          {isAllMatchingSelected ? (
            <span>
              All {totalCount} records are selected.{" "}
              <Button
                variant="link"
                size="sm"
                className="h-auto p-0"
                onClick={() => {
                   if (onRowSelectionChange) onRowSelectionChange({});
                   onSelectAllMatching(false);
                }}
              >
                Clear selection
              </Button>
            </span>
          ) : (
            <span>
              {Object.keys(rowSelection).length} records on this page are selected.{" "}
              <Button
                variant="link"
                size="sm"
                className="h-auto p-0"
                onClick={() => onSelectAllMatching(true)}
              >
                Select all {totalCount} records
              </Button>
            </span>
          )}
        </div>
      )}
      <div className="rounded-md border relative overflow-hidden">
        {isLoading && (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/50">
            <IconLoader className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        )}
        <div
          className="overflow-x-auto max-h-[600px] outline-none"
          tabIndex={0}
          onKeyDown={handleKeyDown}
          onBlur={() => setFocusedIndex(-1)}
        >
          <Table>
            <TableHeader className="bg-muted sticky top-0 z-10 shadow-sm">
              {table.getHeaderGroups().map((headerGroup) => (
                <TableRow key={headerGroup.id}>
                  {headerGroup.headers.map((header) => {
                    return (
                      <TableHead key={header.id} className="h-10 py-2">
                        {header.isPlaceholder
                          ? null
                          : flexRender(
                              header.column.columnDef.header,
                              header.getContext()
                            )}
                      </TableHead>
                    );
                  })}
                </TableRow>
              ))}
            </TableHeader>
            <TableBody>
              {table.getRowModel().rows?.length ? (
                table.getRowModel().rows.map((row, index) => (
                  <TableRow
                    key={row.id}
                    data-state={row.getIsSelected() && "selected"}
                    className={cn(
                      "group cursor-pointer transition-colors",
                      focusedIndex === index && "bg-muted ring-1 ring-ring ring-inset"
                    )}
                    onClick={() => onRowClick ? onRowClick(row.original) : row.toggleSelected()}
                    onMouseEnter={() => setFocusedIndex(index)}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell key={cell.id} className="py-2">
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext()
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell
                    colSpan={columns.length}
                    className="h-24 text-center"
                  >
                    No results.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </div>
      </div>
      <div className="flex items-center justify-between px-2">
        <div className="flex items-center gap-2">
          <p className="text-sm font-medium">Rows per page</p>
          <Select
            value={`${table.getState().pagination.pageSize}`}
            onValueChange={(value) => {
              table.setPageSize(Number(value));
            }}
          >
            <SelectTrigger className="h-8 w-[70px]">
              <SelectValue placeholder={table.getState().pagination.pageSize} />
            </SelectTrigger>
            <SelectContent side="top">
              {[10, 20, 30, 40, 50].map((pageSize) => (
                <SelectItem key={pageSize} value={`${pageSize}`}>
                  {pageSize}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="flex items-center gap-6 lg:gap-8">
          <div className="flex w-[100px] items-center justify-center text-sm font-medium">
            Page {table.getState().pagination.pageIndex + 1} of{" "}
            {table.getPageCount()}
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              className="hidden h-8 w-8 p-0 lg:flex"
              onClick={() => table.setPageIndex(0)}
              disabled={!table.getCanPreviousPage()}
            >
              <span className="sr-only">Go to first page</span>
              <IconChevronsLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              className="h-8 w-8 p-0"
              onClick={() => table.previousPage()}
              disabled={!table.getCanPreviousPage()}
            >
              <span className="sr-only">Go to previous page</span>
              <IconChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              className="h-8 w-8 p-0"
              onClick={() => table.nextPage()}
              disabled={!table.getCanNextPage()}
            >
              <span className="sr-only">Go to next page</span>
              <IconChevronRight className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              className="hidden h-8 w-8 p-0 lg:flex"
              onClick={() => table.setPageIndex(table.getPageCount() - 1)}
              disabled={!table.getCanNextPage()}
            >
              <span className="sr-only">Go to last page</span>
              <IconChevronsRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

