import { prisma } from "@/lib/prisma";
import { Prisma } from "@prisma/client";
import { getWebchatRolloutConfig } from "@/lib/webchat-rollout";

const WINDOW_HOURS = 24;
const WINDOW_MS = WINDOW_HOURS * 60 * 60 * 1000;

export type WebchatMonitoringSnapshot = {
  generatedAt: string;
  windowHours: number;
  rollout: ReturnType<typeof getWebchatRolloutConfig>;
  promotion: {
    currentStage: "off" | "pilot" | "tiered" | "ga";
    recommendedStage: "pilot" | "tiered" | "ga" | null;
    status: "hold" | "ready" | "stable";
    summary: string;
    blockers: string[];
  };
  totals: {
    totalSites: number;
    activeSites: number;
    sitesWithTraffic: number;
    idleSites: number;
    sessions24h: number;
    conversations24h: number;
    messages24h: number;
    widgetEvents24h: number;
    errorEvents24h: number;
    errorRate24h: number;
    lastActivityAt: string | null;
  };
  reasonCounts: {
    blockedOrigin: number;
    rateLimit: number;
    invalidToken: number;
    invalidInitChallenge: number;
    botMitigation: number;
    messageError: number;
    rolloutDisabled: number;
    unknown: number;
  };
  recentErrors: Array<{
    id: string;
    createdAt: string;
    tenantId: string;
    tenantName: string;
    botName: string;
    siteName: string;
    reason: string;
    stage: string | null;
    message: string | null;
  }>;
  trackedTenants: Array<{
    tenantId: string;
    tenantName: string;
    planName: string | null;
    siteCount: number;
    activeSiteCount: number;
    sessions24h: number;
    widgetEvents24h: number;
    errorEvents24h: number;
    errorRate24h: number;
    lastActivityAt: string | null;
    rolloutRole: "pilot" | "force-enabled" | "force-disabled";
  }>;
};

export type WebchatPromotionEvaluationInput = {
  mode: "off" | "pilot" | "tiered" | "ga";
  errorRate24h: number;
  reasonCounts: WebchatMonitoringSnapshot["reasonCounts"];
  trackedTenants: Array<{
    rolloutRole: "pilot" | "force-enabled" | "force-disabled";
    sessions24h: number;
    widgetEvents24h: number;
  }>;
};

export type WebchatPromotionDecision = WebchatMonitoringSnapshot["promotion"];

export function evaluateWebchatPromotion(
  input: WebchatPromotionEvaluationInput,
): WebchatPromotionDecision {
  const promotionBlockers: string[] = [];
  let recommendedStage: "pilot" | "tiered" | "ga" | null = null;
  let promotionStatus: "hold" | "ready" | "stable" = "hold";
  let promotionSummary =
    "Collect stable pilot telemetry before widening rollout.";

  const hasPilotCandidates = input.trackedTenants.some(
    (tenant) => tenant.rolloutRole !== "force-disabled",
  );
  const hasTrackedTraffic = input.trackedTenants.some(
    (tenant) => tenant.widgetEvents24h > 0 || tenant.sessions24h > 0,
  );

  if (
    !hasPilotCandidates &&
    (input.mode === "pilot" || input.mode === "tiered")
  ) {
    promotionBlockers.push(
      "No pilot tenants or force-enabled tenants are configured.",
    );
  }

  if (
    (input.mode === "pilot" || input.mode === "tiered") &&
    !hasTrackedTraffic
  ) {
    promotionBlockers.push(
      "Tracked pilot tenants have no traffic in the last 24 hours.",
    );
  }

  if (input.errorRate24h > 0.03) {
    promotionBlockers.push(
      "Widget error budget is above the 3% rollout threshold.",
    );
  }

  if (input.reasonCounts.blockedOrigin > 5) {
    promotionBlockers.push(
      "Blocked-origin incidents are above the daily rollout threshold.",
    );
  }

  if (input.reasonCounts.rateLimit > 10) {
    promotionBlockers.push(
      "Rate-limit incidents are above the daily pilot threshold.",
    );
  }

  if (
    input.reasonCounts.messageError > 0 ||
    input.reasonCounts.invalidToken > 0
  ) {
    promotionBlockers.push(
      "Recent message_error or invalid_token incidents still need review.",
    );
  }

  if (input.mode === "off") {
    recommendedStage = hasPilotCandidates ? "pilot" : null;
    promotionStatus = hasPilotCandidates ? "ready" : "hold";
    promotionSummary = hasPilotCandidates
      ? "Internal checks are done; the next operational step is enabling pilot mode."
      : "Configure at least one pilot tenant before enabling the rollout.";
  } else if (input.mode === "pilot") {
    if (promotionBlockers.length === 0) {
      recommendedStage = "tiered";
      promotionStatus = "ready";
      promotionSummary =
        "Pilot telemetry is within thresholds; the next operational step is promoting to tiered rollout.";
    } else {
      recommendedStage = null;
      promotionStatus = "hold";
      promotionSummary =
        "Stay in pilot mode until the blocking rollout signals are resolved.";
    }
  } else if (input.mode === "tiered") {
    if (
      promotionBlockers.length === 0 &&
      input.reasonCounts.rolloutDisabled === 0
    ) {
      recommendedStage = "ga";
      promotionStatus = "ready";
      promotionSummary =
        "Tiered rollout looks stable; the next operational step is preparing GA promotion.";
    } else {
      recommendedStage = null;
      promotionStatus = "hold";
      promotionSummary =
        "Stay in tiered mode until rollout denials and blocking signals are resolved.";
      if (input.reasonCounts.rolloutDisabled > 0) {
        promotionBlockers.push(
          "Rollout-disabled incidents are still occurring during tiered rollout.",
        );
      }
    }
  } else {
    recommendedStage = null;
    promotionStatus = promotionBlockers.length === 0 ? "stable" : "hold";
    promotionSummary =
      promotionBlockers.length === 0
        ? "GA mode is active and current telemetry looks stable."
        : "GA mode is active, but rollout health needs attention.";
  }

  return {
    currentStage: input.mode,
    recommendedStage,
    status: promotionStatus,
    summary: promotionSummary,
    blockers: Array.from(new Set(promotionBlockers)),
  };
}

function getPayloadString(payload: unknown, key: string): string | null {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return null;
  }

  const value = (payload as Record<string, unknown>)[key];
  return typeof value === "string" ? value : null;
}

function asNumber(value: bigint | number | string | null | undefined): number {
  if (typeof value === "bigint") {
    return Number(value);
  }

  if (typeof value === "number") {
    return value;
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }

  return 0;
}

export async function getLiveWebchatSessions() {
  const since = new Date(Date.now() - 60 * 60 * 1000); // last 1 hour for "live"

  const sessions = await prisma.webChatSession.findMany({
    where: {
      lastSeenAt: { gte: since }
    },
    include: {
      conversation: {
        select: {
          id: true,
          status: true,
          botPaused: true,
          messages: {
            orderBy: { createdAt: "desc" },
            take: 1
          }
        }
      },
      site: {
        select: {
          name: true,
          tenant: {
            select: { name: true }
          }
        }
      }
    },
    orderBy: {
      lastSeenAt: "desc"
    },
    take: 50
  });

  return sessions.map(session => {
    const meta = session.metadata as any;
    return {
      id: session.id,
      visitorId: session.visitorId,
      conversationId: session.conversationId,
      siteName: session.site.name,
      tenantName: session.site.tenant.name,
      status: session.conversation.status,
      botPaused: session.conversation.botPaused,
      location: meta?.location || "Unknown",
      device: meta?.device || "Unknown",
      lastSeenAt: session.lastSeenAt.toISOString(),
      createdAt: session.createdAt.toISOString(),
      durationMs: session.lastSeenAt.getTime() - session.createdAt.getTime(),
      lastMessage: session.conversation.messages[0]?.content || null
    };
  });
}

export async function getWebchatAnalytics() {
  const since = new Date(Date.now() - 24 * 60 * 60 * 1000); // 24 hours

  // Basic hourly bucketing
  const hourlyData = await prisma.$queryRaw<Array<{ hour: Date, sessionCount: bigint, errorCount: bigint }>>`
    WITH hours AS (
      SELECT generate_series(
        date_trunc('hour', ${since}::timestamp),
        date_trunc('hour', now()::timestamp),
        '1 hour'::interval
      ) AS hour
    ),
    session_counts AS (
      SELECT date_trunc('hour', "createdAt") as hour, count(*) as count
      FROM "webchat_sessions"
      WHERE "createdAt" >= ${since}
      GROUP BY 1
    ),
    error_counts AS (
      SELECT date_trunc('hour', "createdAt") as hour, count(*) as count
      FROM "webchat_events"
      WHERE "createdAt" >= ${since} AND "type" = 'ERROR'
      GROUP BY 1
    )
    SELECT h.hour, COALESCE(s.count, 0) as "sessionCount", COALESCE(e.count, 0) as "errorCount"
    FROM hours h
    LEFT JOIN session_counts s ON h.hour = s.hour
    LEFT JOIN error_counts e ON h.hour = e.hour
    ORDER BY h.hour ASC
  `;

  return hourlyData.map(d => ({
    time: d.hour.toISOString(),
    sessions: Number(d.sessionCount),
    errors: Number(d.errorCount)
  }));
}

export async function getSessionHistory(sessionId: string) {
  const session = await prisma.webChatSession.findUnique({
    where: { id: sessionId },
    include: {
      conversation: {
        include: {
          messages: {
            orderBy: { createdAt: "asc" }
          }
        }
      },
      events: {
        orderBy: { createdAt: "asc" }
      }
    }
  });

  if (!session) return null;

  return {
    messages: session.conversation.messages.map(m => ({
      id: m.id,
      content: m.content,
      direction: m.direction,
      createdAt: m.createdAt.toISOString(),
      source: m.source
    })),
    events: session.events.map(e => ({
      id: e.id,
      type: e.type,
      payload: e.payload,
      createdAt: e.createdAt.toISOString()
    }))
  };
}

export async function getAdminWebchatMonitoringSnapshot(): Promise<WebchatMonitoringSnapshot> {
  const since = new Date(Date.now() - WINDOW_MS);
  const rollout = getWebchatRolloutConfig();
  const trackedTenantIds = Array.from(
    new Set([
      ...rollout.pilotTenantIds,
      ...rollout.enabledTenantIds,
      ...rollout.disabledTenantIds,
    ]),
  );

  const [
    totalSites,
    activeSites,
    sessions24h,
    conversations24h,
    messages24h,
    widgetEvents24h,
    errorEvents24h,
    lastSession,
    lastEvent,
    trafficRows,
    reasonRows,
    recentErrors,
    trackedTenants,
    siteRows,
    tenantSessionRows,
    tenantEventRows,
  ] = await Promise.all([
    prisma.webChatSite.count(),
    prisma.webChatSite.count({ where: { isActive: true } }),
    prisma.webChatSession.count({ where: { lastSeenAt: { gte: since } } }),
    prisma.crmConversation.count({
      where: {
        channel: "web",
        updatedAt: { gte: since },
      },
    }),
    prisma.crmMessage.count({
      where: {
        createdAt: { gte: since },
        conversation: {
          channel: "web",
        },
      },
    }),
    prisma.webChatEvent.count({ where: { createdAt: { gte: since } } }),
    prisma.webChatEvent.count({
      where: {
        createdAt: { gte: since },
        type: "ERROR",
      },
    }),
    prisma.webChatSession.findFirst({
      orderBy: { lastSeenAt: "desc" },
      select: { lastSeenAt: true },
    }),
    prisma.webChatEvent.findFirst({
      orderBy: { createdAt: "desc" },
      select: { createdAt: true },
    }),
    prisma.$queryRaw<Array<{ count: bigint }>>`
      SELECT COUNT(DISTINCT "siteId")::bigint AS count
      FROM "webchat_sessions"
      WHERE "lastSeenAt" >= ${since}
    `,
    prisma.$queryRaw<Array<{ reason: string | null; count: bigint }>>`
      SELECT COALESCE(payload->>'reason', 'unknown') AS reason,
             COUNT(*)::bigint AS count
      FROM "webchat_events"
      WHERE "type" = 'ERROR'
        AND "createdAt" >= ${since}
      GROUP BY 1
      ORDER BY 2 DESC
    `,
    prisma.webChatEvent.findMany({
      where: { type: "ERROR" },
      orderBy: { createdAt: "desc" },
      take: 12,
      select: {
        id: true,
        createdAt: true,
        payload: true,
        site: {
          select: {
            name: true,
            bot: {
              select: { name: true },
            },
            tenant: {
              select: {
                id: true,
                name: true,
              },
            },
          },
        },
      },
    }),
    trackedTenantIds.length === 0
      ? Promise.resolve([])
      : prisma.tenant.findMany({
          where: { id: { in: trackedTenantIds } },
          select: {
            id: true,
            name: true,
            subscriptions: {
              select: {
                status: true,
                plan: {
                  select: {
                    name: true,
                  },
                },
              },
            },
          },
        }),
    trackedTenantIds.length === 0
      ? Promise.resolve([])
      : prisma.webChatSite.findMany({
          where: { tenantId: { in: trackedTenantIds } },
          select: {
            id: true,
            tenantId: true,
            isActive: true,
          },
        }),
    trackedTenantIds.length === 0
      ? Promise.resolve([])
      : prisma.$queryRaw<
          Array<{
            tenantId: string;
            sessionsCount: bigint;
            lastActivityAt: Date | null;
          }>
        >`
          SELECT ws."tenantId" AS "tenantId",
                 COUNT(*)::bigint AS "sessionsCount",
                 MAX(s."lastSeenAt") AS "lastActivityAt"
          FROM "webchat_sessions" s
          INNER JOIN "webchat_sites" ws ON ws.id = s."siteId"
          WHERE ws."tenantId" IN (${Prisma.join(trackedTenantIds)})
            AND s."lastSeenAt" >= ${since}
          GROUP BY ws."tenantId"
        `,
    trackedTenantIds.length === 0
      ? Promise.resolve([])
      : prisma.$queryRaw<
          Array<{
            tenantId: string;
            widgetEventsCount: bigint;
            errorEventsCount: bigint;
            lastEventAt: Date | null;
          }>
        >`
          SELECT ws."tenantId" AS "tenantId",
                 COUNT(*)::bigint AS "widgetEventsCount",
                 COUNT(*) FILTER (WHERE e."type" = 'ERROR')::bigint AS "errorEventsCount",
                 MAX(e."createdAt") AS "lastEventAt"
          FROM "webchat_events" e
          INNER JOIN "webchat_sites" ws ON ws.id = e."siteId"
          WHERE ws."tenantId" IN (${Prisma.join(trackedTenantIds)})
            AND e."createdAt" >= ${since}
          GROUP BY ws."tenantId"
        `,
  ]);

  const lastActivityAt = [
    lastSession?.lastSeenAt?.getTime(),
    lastEvent?.createdAt?.getTime(),
  ]
    .filter((value): value is number => typeof value === "number")
    .sort((left, right) => right - left)[0];

  const reasonCounts = {
    blockedOrigin: 0,
    rateLimit: 0,
    invalidToken: 0,
    invalidInitChallenge: 0,
    botMitigation: 0,
    messageError: 0,
    rolloutDisabled: 0,
    unknown: 0,
  };

  for (const row of reasonRows) {
    const count = asNumber(row.count);
    switch (row.reason) {
      case "blocked_origin":
        reasonCounts.blockedOrigin += count;
        break;
      case "rate_limit":
        reasonCounts.rateLimit += count;
        break;
      case "invalid_token":
        reasonCounts.invalidToken += count;
        break;
      case "invalid_init_challenge":
        reasonCounts.invalidInitChallenge += count;
        break;
      case "bot_mitigation":
        reasonCounts.botMitigation += count;
        break;
      case "message_error":
        reasonCounts.messageError += count;
        break;
      case "rollout_disabled":
        reasonCounts.rolloutDisabled += count;
        break;
      default:
        reasonCounts.unknown += count;
        break;
    }
  }

  const sitesWithTraffic = asNumber(trafficRows[0]?.count);
  const errorRate24h =
    widgetEvents24h === 0 ? 0 : errorEvents24h / widgetEvents24h;

  const siteStatsByTenant = new Map<
    string,
    { siteCount: number; activeSiteCount: number }
  >();
  for (const site of siteRows) {
    const stats = siteStatsByTenant.get(site.tenantId) || {
      siteCount: 0,
      activeSiteCount: 0,
    };
    stats.siteCount += 1;
    if (site.isActive) {
      stats.activeSiteCount += 1;
    }
    siteStatsByTenant.set(site.tenantId, stats);
  }

  const sessionStatsByTenant = new Map(
    tenantSessionRows.map((row) => [
      row.tenantId,
      {
        sessions24h: asNumber(row.sessionsCount),
        lastActivityAt: row.lastActivityAt,
      },
    ]),
  );

  const eventStatsByTenant = new Map(
    tenantEventRows.map((row) => [
      row.tenantId,
      {
        widgetEvents24h: asNumber(row.widgetEventsCount),
        errorEvents24h: asNumber(row.errorEventsCount),
        lastEventAt: row.lastEventAt,
      },
    ]),
  );

  const trackedTenantSummaries = trackedTenants
    .map((tenant) => {
      const siteStats = siteStatsByTenant.get(tenant.id) || {
        siteCount: 0,
        activeSiteCount: 0,
      };
      const sessionStats = sessionStatsByTenant.get(tenant.id) || {
        sessions24h: 0,
        lastActivityAt: null,
      };
      const eventStats = eventStatsByTenant.get(tenant.id) || {
        widgetEvents24h: 0,
        errorEvents24h: 0,
        lastEventAt: null,
      };

      const lastActivityAt = [
        sessionStats.lastActivityAt?.getTime(),
        eventStats.lastEventAt?.getTime(),
      ]
        .filter((value): value is number => typeof value === "number")
        .sort((left, right) => right - left)[0];

      const widgetEventsForTenant = eventStats.widgetEvents24h;
      const errorRateForTenant =
        widgetEventsForTenant === 0
          ? 0
          : eventStats.errorEvents24h / widgetEventsForTenant;

      let rolloutRole: "pilot" | "force-enabled" | "force-disabled" = "pilot";
      if (rollout.disabledTenantIds.includes(tenant.id)) {
        rolloutRole = "force-disabled";
      } else if (rollout.enabledTenantIds.includes(tenant.id)) {
        rolloutRole = "force-enabled";
      }

      const subscriptionCandidates = Array.isArray(tenant.subscriptions)
        ? tenant.subscriptions
        : tenant.subscriptions
          ? [tenant.subscriptions]
          : [];
      const activeSubscription = subscriptionCandidates.find((subscription) =>
        ["active", "trialing"].includes(subscription.status),
      );

      return {
        tenantId: tenant.id,
        tenantName: tenant.name,
        planName: activeSubscription?.plan.name || null,
        siteCount: siteStats.siteCount,
        activeSiteCount: siteStats.activeSiteCount,
        sessions24h: sessionStats.sessions24h,
        widgetEvents24h: widgetEventsForTenant,
        errorEvents24h: eventStats.errorEvents24h,
        errorRate24h: errorRateForTenant,
        lastActivityAt: lastActivityAt
          ? new Date(lastActivityAt).toISOString()
          : null,
        rolloutRole,
      };
    })
    .sort((left, right) => left.tenantName.localeCompare(right.tenantName));

  const promotion = evaluateWebchatPromotion({
    mode: rollout.mode,
    errorRate24h,
    reasonCounts,
    trackedTenants: trackedTenantSummaries,
  });

  return {
    generatedAt: new Date().toISOString(),
    windowHours: WINDOW_HOURS,
    rollout,
    promotion,
    totals: {
      totalSites,
      activeSites,
      sitesWithTraffic,
      idleSites: Math.max(activeSites - sitesWithTraffic, 0),
      sessions24h,
      conversations24h,
      messages24h,
      widgetEvents24h,
      errorEvents24h,
      errorRate24h,
      lastActivityAt: lastActivityAt
        ? new Date(lastActivityAt).toISOString()
        : null,
    },
    reasonCounts,
    recentErrors: recentErrors.map((event) => ({
      id: event.id,
      createdAt: event.createdAt.toISOString(),
      tenantId: event.site.tenant.id,
      tenantName: event.site.tenant.name,
      botName: event.site.bot.name,
      siteName: event.site.name,
      reason: getPayloadString(event.payload, "reason") || "unknown",
      stage: getPayloadString(event.payload, "stage"),
      message:
        getPayloadString(event.payload, "message") ||
        getPayloadString(event.payload, "error") ||
        getPayloadString(event.payload, "origin") ||
        getPayloadString(event.payload, "rolloutReason"),
    })),
    trackedTenants: trackedTenantSummaries,
  };
}

import { prisma } from "@/lib/prisma";
import { streamText, Output, ModelMessage } from "ai";
import { getAiModel, AiProvider } from "@/lib/ai-service";

export interface AiFallbackOptions {
  botId: string;
  conversationId: string;
  messages: ModelMessage[];
  planName: string;
  charLimit?: number;
}

/**
 * Fetches bot context and last N messages, builds prompt, and streams AI fallback response.
 * - For pro/business: injects bot context and last N messages (char limit)
 * - For free/starter: uses simple prompt
 */
export async function aiFallback({
  botId,
  conversationId,
  messages,
  planName,
  charLimit = 1000,
}: AiFallbackOptions) {
  // Fetch bot and tenant context
  const bot = await prisma.bot.findUnique({
    where: { id: botId },
    select: {
      context: true,
      name: true,
      tenant: {
        select: {
          aiProvider: true,
          aiApiKey: true,
          aiModel: true,
        },
      },
    },
  });

  // Fetch last N messages (limit by char count)
  const lastMessages = await prisma.crmMessage.findMany({
    where: { conversationId },
    orderBy: { createdAt: "desc" },
    take: 10, // fetch up to 10, trim by char below
    select: { content: true, source: true, createdAt: true },
  });
  // Reverse to chronological order
  const ordered = lastMessages.reverse();
  const contextMessages: string[] = [];
  let totalChars = 0;
  for (const msg of ordered) {
    const line = `[${msg.source}] ${msg.content}`;
    if (totalChars + line.length > charLimit) break;
    contextMessages.push(line);
    totalChars += line.length;
  }

  // Build prompt
  let promptMessages: ModelMessage[] = messages;
  const plan = planName.toLowerCase();
  if (plan.includes("pro") || plan.includes("business")) {
    // Inject bot context and last messages
    const contextBlock = [
      bot?.context ? `Bot Context: ${JSON.stringify(bot.context)}` : null,
      contextMessages.length
        ? `Recent Conversation:\n${contextMessages.join("\n")}`
        : null,
    ]
      .filter(Boolean)
      .join("\n\n");
    promptMessages = [
      { role: "system", content: contextBlock },
      ...messages,
    ] as ModelMessage[];
  }
  // For free/starter, just use messages

  const provider = (bot?.tenant?.aiProvider as AiProvider) || "default";
  const model = getAiModel({
    provider,
    apiKey: bot?.tenant?.aiApiKey || undefined,
    model: bot?.tenant?.aiModel || undefined,
    planName,
    task: "chat",
  });

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 15000);

  try {
    try {
      const aiStream = await streamText({
        model,
        messages: promptMessages,
        output: Output.text(),
        abortSignal: controller.signal,
      });
      return aiStream;
    } catch (primaryError: any) {
      // Check for rate limit errors (429 or RESOURCE_EXHAUSTED)
      const isRateLimit = 
        String(primaryError).includes("429") || 
        String(primaryError).includes("RESOURCE_EXHAUSTED");

      if (isRateLimit) {
        console.warn("[AI Fallback] Rate limit hit on primary model. Failing over to Gemma...");

        const fallbackModel = getAiModel({
          provider,
          apiKey: bot?.tenant?.aiApiKey || undefined,
          model: bot?.tenant?.aiModel || undefined,
          planName,
          task: "chat",
          isFallback: true,
        });

        const fallbackStream = await streamText({
          model: fallbackModel,
          messages: promptMessages,
          output: Output.text(),
          abortSignal: controller.signal,
        });
        return fallbackStream;
      }

      // Re-throw if not a rate limit error
      throw primaryError;
    }
  } finally {
    clearTimeout(timeoutId);
  }
}

import { google, createGoogleGenerativeAI } from "@ai-sdk/google";
import { openai, createOpenAI } from "@ai-sdk/openai";
import { anthropic, createAnthropic } from "@ai-sdk/anthropic";
import { LanguageModel } from "ai";

export type AiProvider = "default" | "gemini" | "openai" | "anthropic";
export type AiTask = "onboarding" | "chat" | "general";

export interface GetAiModelOptions {
  provider: AiProvider;
  apiKey?: string;
  model?: string;
  planName?: string;
  task?: AiTask;
  isFallback?: boolean;
}

/**
 * Returns the appropriate AI model based on provider, optional custom model, task type, and plan.
 * If a custom API key is provided, it uses it for the specified provider.
 * "default" provider uses system-managed Gemini/Gemma models.
 */
export function getAiModel({
  provider,
  apiKey,
  model,
  planName = "free",
  task = "general",
  isFallback = false,
}: GetAiModelOptions): LanguageModel {
  const plan = planName.toLowerCase();
  const isPro = plan.includes("pro") || plan.includes("business");

  // Logic: Onboarding ALWAYS prefers higher reasoning models.
  // Chat fallback ALWAYS prefers high-speed, low-cost models.
  const isHighPriority = task === "onboarding" || isPro;

  switch (provider) {
    case "openai": {
      const client = createOpenAI({
        apiKey: apiKey || process.env.OPENAI_API_KEY,
      });
      return client(model || (isHighPriority ? "gpt-4o" : "gpt-4o-mini"));
    }

    case "anthropic": {
      const client = createAnthropic({
        apiKey: apiKey || process.env.ANTHROPIC_API_KEY,
      });
      return client(
        model || (isHighPriority ? "claude-3-5-sonnet-latest" : "claude-3-haiku-latest"),
      );
    }

    case "gemini":
    case "default":
    default: {
      // System-managed Gemini/Gemma
      const client = createGoogleGenerativeAI({
        apiKey: apiKey || process.env.GOOGLE_GENERATIVE_AI_API_KEY,
      });

      // If this is a fallback request, use a high-RPM Gemma model
      if (isFallback) {
        return client("gemma-3-27b"); // Your highest RPM model (30 RPM)
      }

      // Task-specific defaults for the available Gemini versions (2.5 and 3)
      let defaultModel = "gemini-2.5-flash"; 
      if (task === "onboarding") {
        defaultModel = "gemini-3-flash"; 
      }

      return client(model || defaultModel);
    }
  }
}

import Stripe from "stripe";
import { prisma } from "@/lib/prisma";
import { stripe } from "@/lib/stripe";
import { handlePlanDowngrade } from "./subscription";

/**
 * Robust subscription synchronization service
 * Ensures local database projections match Stripe source of truth
 */
export async function syncSubscription(
  tenantId: string,
  stripeSubId: string,
) {
  if (!stripe) throw new Error("Stripe not initialized");

  const sub = (await stripe.subscriptions.retrieve(stripeSubId)) as any;
  const stripeCustomerId = sub.customer as string;

  // Ensure tenantId is valid and exists in DB
  let tenant = await prisma.tenant.findUnique({ where: { id: tenantId } });

  if (!tenant) {
    console.warn(`[Billing] Tenant ${tenantId} not found. Attempting fallback via Customer ID ${stripeCustomerId}...`);
    // Fallback: Try to find tenant by stripeCustomerId in existing subscriptions
    const existingSub = await prisma.subscription.findUnique({
      where: { stripeCustomerId }
    });
    if (existingSub) {
      tenantId = existingSub.tenantId;
      tenant = await prisma.tenant.findUnique({ where: { id: tenantId } });
    }
  }

  if (!tenant) {
    // If still not found, we cannot proceed as it would violate foreign key constraints (P2003)
    throw new Error(`Tenant not found for ID: ${tenantId}. Cannot sync subscription ${stripeSubId}.`);
  }

  // 1. Map Stripe Product to Internal Plan
  // Prioritize planName from subscription metadata (set during checkout)
  let planName = sub.metadata?.planName;

  if (!planName) {
    const product = await stripe.products.retrieve(
      sub.items.data[0].price.product as string,
    );
    planName = product.metadata?.app_plan_id;

    if (!planName) {
      const nameLower = product.name.toLowerCase();
      // Improved matching order: more specific to less specific
      if (nameLower.includes("business")) planName = "business";
      else if (nameLower.includes("pro")) planName = "pro";
      else if (nameLower.includes("starter")) planName = "starter";
      else planName = "free";
    }
  }

  let dbPlan = await prisma.plan.findUnique({ where: { name: planName } });
  if (!dbPlan) {
    console.warn(`[Billing] Plan '${planName}' not found in DB. Auto-creating...`);

    // Define default limits based on plan name
    let dailyMessageLimit = 100;
    let monthlyMessageLimit = 3000;
    let flowExecutionCap = 100;
    let maxBots = 1;
    let price = 0;
    let displayName = "Free";

    if (planName === "starter") {
      dailyMessageLimit = 500;
      monthlyMessageLimit = 1000;
      flowExecutionCap = 1500;
      maxBots = 3;
      price = 2900;
      displayName = "Starter";
    } else if (planName === "pro") {
      dailyMessageLimit = 2000;
      monthlyMessageLimit = 7500;
      flowExecutionCap = 10000;
      maxBots = 10;
      price = 8900;
      displayName = "Pro";
    } else if (planName === "business") {
      dailyMessageLimit = 5000;
      monthlyMessageLimit = 25000;
      flowExecutionCap = 40000;
      maxBots = 25;
      price = 24900;
      displayName = "Business";
    }

    dbPlan = await prisma.plan.create({
      data: {
        name: planName,
        displayName: displayName,
        price: price,
        currency: "GBP",
        dailyMessageLimit,
        monthlyMessageLimit,
        flowExecutionCap,
        maxBots,
        maxChannelsPerBot: 5,
        maxConversations: 1000,
      },
    });
  }

  // 2. Map Stripe Status to Strict State Machine (Rule #1)
  let status = sub.status.toUpperCase();
  if (status === "UNPAID" || status === "INCOMPLETE_EXPIRED") status = "CANCELED";
  if (status === "INCOMPLETE") status = "PAST_DUE";

  // 3. Handle Downgrade Logic (Rule #7)
  const isDowngradeScheduled = sub.cancel_at_period_end;

  return await prisma.$transaction(async (tx) => {
    const existingSub = await tx.subscription.findUnique({ where: { tenantId } });

    // If downgrading/reverting to free at period end
    if (status === "CANCELED" || (isDowngradeScheduled && sub.status !== "trialing")) {
      // Logic for downgrade consequences can be triggered here or via a separate job at period_end
    }

    const updatedSub = await tx.subscription.upsert({
      where: { tenantId },
      update: {
        stripeId: sub.id,
        stripeCustomerId,
        status: status,
        currentPeriodStart: sub.current_period_start ? new Date(sub.current_period_start * 1000) : new Date(),
        currentPeriodEnd: sub.current_period_end ? new Date(sub.current_period_end * 1000) : new Date(),
        cancelAtPeriodEnd: !!sub.cancel_at_period_end,
        trialEndsAt: sub.trial_end ? new Date(sub.trial_end * 1000) : null,
        planId: dbPlan.id,
        downgradeScheduled: isDowngradeScheduled,
        downgradeEffectiveAt: (isDowngradeScheduled && sub.current_period_end) ? new Date(sub.current_period_end * 1000) : null,
      },
      create: {
        tenantId,
        stripeId: sub.id,
        stripeCustomerId,
        status: status,
        currentPeriodStart: sub.current_period_start ? new Date(sub.current_period_start * 1000) : new Date(),
        currentPeriodEnd: sub.current_period_end ? new Date(sub.current_period_end * 1000) : new Date(),
        cancelAtPeriodEnd: !!sub.cancel_at_period_end,
        trialEndsAt: sub.trial_end ? new Date(sub.trial_end * 1000) : null,
        planId: dbPlan.id,
      },
    });

    // Abuse Prevention: Track trial usage (Rule #9)
    if (status === "TRIALING") {
      await tx.tenant.update({
        where: { id: tenantId },
        data: { trialUsed: true },
      });
    }

    // Apply immediate downgrade consequences if plan actually changed (e.g. mid-cycle adjustment)
    if (existingSub && existingSub.planId !== dbPlan.id) {
       await handlePlanDowngrade(tenantId, dbPlan.id);
    }

    return updatedSub;
  });
}

/**
 * Reconciliation job: Sync all active/trialing subscriptions to prevent drift (Rule #8)
 */
export async function reconcileSubscriptions() {
  if (!stripe) return;

  console.log("[Reconciliation] Starting daily sync...");
  const activeSubs = await prisma.subscription.findMany({
    where: { status: { in: ["ACTIVE", "TRIALING", "PAST_DUE"] } }
  });

  for (const dbSub of activeSubs) {
    try {
      await syncSubscription(dbSub.tenantId, dbSub.stripeId);
    } catch (err) {
      console.error(`[Reconciliation] Failed to sync tenant ${dbSub.tenantId}:`, err);
    }
  }
  console.log("[Reconciliation] Sync complete.");
}

import { prisma } from "./prisma";

/**
 * Creates a tenant-scoped Prisma client using extensions.
 * This ensures that all queries automatically include the tenantId filter.
 */
export function getTenantPrisma(tenantId: string) {
  return prisma.$extends({
    query: {
      $allModels: {
        async $allOperations({ model, operation, args, query }) {
          // List of models that HAVE a tenantId field
          // This should be updated as the schema grows
          const tenantModels = [
            "User",
            "TenantLeadNotificationSettings",
            "TenantChannelStatus",
            "FacebookPage",
            "Subscription",
            "NewsletterSubscriber",
            "DataDeletionRequest",
            "Revenue",
            "Bot",
            "UsageLog",
            "ActivityLog",
            "Contact",
            "WebChatSite",
            "Lead",
            "Flow",
            "OnboardingSession",
            "OnboardingMetrics",
            "CrmConversation",
            "CrmMessage",
            "InternalNote",
          ];

          if (tenantModels.includes(model)) {
            const tenantFilter = { tenantId };
            const anyArgs = args as any;

            if (["findFirst", "findUnique", "findMany", "count", "aggregate", "groupBy"].includes(operation)) {
              anyArgs.where = { ...anyArgs.where, ...tenantFilter };
            } else if (["update", "updateMany", "delete", "deleteMany"].includes(operation)) {
              anyArgs.where = { ...anyArgs.where, ...tenantFilter };
            } else if (operation === "upsert") {
              anyArgs.where = { ...anyArgs.where, ...tenantFilter };
              anyArgs.create = { ...anyArgs.create, ...tenantFilter };
              anyArgs.update = { ...anyArgs.update, ...tenantFilter };
            } else if (operation === "create" || operation === "createMany") {
              if (Array.isArray(anyArgs.data)) {
                anyArgs.data = anyArgs.data.map((item: any) => ({ ...item, ...tenantFilter }));
              } else {
                anyArgs.data = { ...anyArgs.data, ...tenantFilter };
              }
            }
          }

          return query(args);
        },
      },
    },
  });
}

import { PrismaClient } from "@prisma/client";
