    function renderResponseEntries(entries) {
      if (!Array.isArray(entries) || entries.length === 0) {
        return Promise.resolve();
      }

      var chain = Promise.resolve();

      entries.forEach(function (entry) {
        chain = chain.then(function () {
          if (!entry || typeof entry.type !== "string") {
            return;
          }

          if (entry.type === "typing") {
            showBotTyping();
            return delay(entry.durationMs || 0).then(function () {
              hideBotTyping();
            });
          }

          hideBotTyping();
          if (entry.type === "text" && typeof entry.text === "string") {
            addMessage("bot", entry.text);
          }
        });
      });

      return chain.finally(function () {
        hideBotTyping();
      });
    }

    function sendMessage() {
      if (isSending) {
        return;
      }

      var text = input.value.trim();
      if (!text) {
        return;
      }

      if (!conversationId || !botId || !token) {
        addSystemNote(
          "Please wait for chat to fully load before sending a message.",
        );
        return;
      }

      input.value = "";
      addMessage("user", text);
      isSending = true;
      sendButton.disabled = true;

      trackEvent("MESSAGE", {
        url: window.location.href,
        direction: "outbound",
        messageLength: text.length,
      });

      // Track with Plausible if available
      if (typeof window.plausible === "function") {
        // Track general message sent event
        window.plausible("Webchat Message Sent", {
          props: {
            url: window.location.href,
            messageLength: text.length,
          },
        });

        // Track "first_message_sent" goal if this is the first message in the session
        var hasTrackedFirstMessage = false;
        try {
          hasTrackedFirstMessage = !!window.sessionStorage.getItem(
            "replybase_tracked_first_message",
          );
        } catch (e) {}

        if (!hasTrackedFirstMessage) {
          window.plausible("first_message_sent", {
            props: {
              url: window.location.href,
            },
          });
          try {
            window.sessionStorage.setItem("replybase_tracked_first_message", "1");
          } catch (e) {}
        }
      }

      request("/api/webchat/message", "POST", {
        token: token,
        conversationId: conversationId,
        botId: botId,
        message: text,
        planName: window.ReplyBaseWebchatPlanName || "pro",
        metadata: buildRuntimeMetadata(),
        botSignals: buildBotSignals(),
      })
        .then(function (data) {
          var entries = normalizeResponseEntries(data);
          if (!entries.length) {
            if (
              data &&
              data.meta &&
              typeof data.meta.mode === "string" &&
              data.meta.mode.indexOf("human_handoff") === 0
            ) {
              return;
            }
            addSystemNote("No response received");
            return;
          }

          return renderResponseEntries(entries);
        })
        .catch(function (err) {
          hideBotTyping();
          trackEvent("ERROR", {
            url: window.location.href,
            stage: "message",
            reason: "request_failed",
            message: err && err.message ? err.message : "Message failed",
          });
          addSystemNote(err && err.message ? err.message : "Message failed");
        })
        .finally(function () {
          hideBotTyping();
          isSending = false;
          sendButton.disabled = false;
        });
    }

    function openPanel() {
