    function pollAgentReplies() {
      if (!token) {
        return Promise.resolve(null);
      }

      var query = "token=" + encodeURIComponent(token);
      if (lastHumanReplyCursor) {
        query += "&after=" + encodeURIComponent(lastHumanReplyCursor);
