  function setStoredSession(nextSession) {
    if (!canUsePersistentStorage()) {
      return;
    }

    try {
      window.localStorage.setItem(
        STORAGE_KEY_PREFIX + ":" + storageScope,
        JSON.stringify(nextSession),
      );
    } catch {
      // Ignore storage write issues.
    }
