/**
 * Add a new flow for a specific user's tenant.
 * Can be created from a template or a simple welcome flow.
 *
 * Usage:
 *   pnpm tsx scripts/add-user-flow.ts --email=user@example.com --template=restaurant
 *   pnpm tsx scripts/add-user-flow.ts --id=USER_ID --name="Custom Flow"
 *
 * Available templates:
 *   welcome, lead-generation, lead-capture, real-estate, services, agencies, booking,
 *   boutique-gym, personal-training, crossfit-gym, boot-camp, yoga-studio, hair-salon,
 *   barbershop, day-spa, nail-salon, cleaning-services, landscaping, handyman, pet-care,
 *   care-services, restaurant, hotel, golf-club
 */

import "dotenv/config";
import { prisma } from "@/lib/prisma";
import { getAvailableTemplates, FlowTemplateCategory } from "@/lib/flow-templates";
import minimist from "minimist";
import { Prisma } from "@prisma/client";

async function main() {
  const args = minimist(process.argv.slice(2));
  const email = args.email;
  const id = args.id;
  const templateKey = args.template;
  const customName = args.name;

  if (!email && !id) {
    console.error("Usage: pnpm tsx scripts/add-user-flow.ts --email=user@example.com [--template=category] [--name='Flow Name']");
    process.exit(1);
  }

  try {
    const user = await prisma.user.findFirst({
      where: email ? { email } : { id },
      select: { id: true, tenantId: true, email: true },
    });

    if (!user) {
      console.error(`❌ User not found with ${email ? "email: " + email : "id: " + id}`);
      process.exit(1);
    }

    let flowName = customName || "New Flow";
    let flowDescription = "A new conversational flow.";
    let nodes: Record<string, unknown>[] = [];

    if (templateKey) {
      const templates = getAvailableTemplates();
      const template = templates.find(t => t.category === templateKey);

      if (!template) {
        console.error(`❌ Template '${templateKey}' not found.`);
        console.log("Available categories:", templates.map(t => t.category).join(", "));
        process.exit(1);
      }

      flowName = customName || template.name;
      flowDescription = template.description;
      nodes = template.nodes;
      console.log(`📝 Using template: ${template.name}`);
    } else {
      // Default simple flow if no template provided
      nodes = [
        {
          type: "message",
          content: { text: "Hello! How can I help you today?" },
          order: 0
        },
        {
          type: "input",
          content: { text: "What's your name?", variableName: "name", inputType: "text" },
          order: 1
        },
        {
          type: "message",
          content: { text: "Nice to meet you, {{name}}!" },
          order: 2
        }
      ];
    }

    const flow = await prisma.flow.create({
      data: {
        name: flowName,
        description: flowDescription,
        tenantId: user.tenantId,
        ownerId: user.id,
        isActive: true,
        nodes: {
          create: nodes.map(n => ({
            type: n.type,
            content: n.content as Prisma.InputJsonValue,
            order: n.order
          }))
        }
      }
    });

    console.log(`✅ Flow created successfully: ${flow.name} (${flow.id})`);
    console.log(`🔗 Assigned to tenant: ${user.tenantId}`);

  } catch (error) {
    console.error("❌ Error adding flow:", error);
    process.exit(1);
  } finally {
    await prisma.$disconnect();
  }
}

main();

import { prisma } from "../lib/prisma";
import { execSync } from "child_process";
import fs from "fs";
import path from "path";

async function runLoadTest(name: string, scriptPath: string) {
  console.log(`Starting load test: ${name}...`);
  const resultsDir = path.join(process.cwd(), "test-results");
  if (!fs.existsSync(resultsDir)) {
    fs.mkdirSync(resultsDir);
  }

  const reportPath = path.join(resultsDir, `load-report-${Date.now()}.json`);
  const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000";

  try {
    // Expect k6 to be in the PATH
    console.log(`Executing: k6 run --summary-export=${reportPath} -e BASE_URL=${baseUrl} ${scriptPath}`);
    execSync(`k6 run --summary-export=${reportPath} -e BASE_URL=${baseUrl} ${scriptPath}`, { stdio: 'inherit' });

    if (fs.existsSync(reportPath)) {
      const summary = JSON.parse(fs.readFileSync(reportPath, "utf-8"));

      const metrics = {
        p50: summary.metrics.http_req_duration?.values['p(50)'] || 0,
        p95: summary.metrics.http_req_duration?.values['p(95)'] || 0,
        p99: summary.metrics.http_req_duration?.values['p(99)'] || 0,
        throughput: summary.metrics.http_reqs?.values.rate || 0,
        errorRate: summary.metrics.http_req_failed?.values.rate || 0,
        totalRequests: summary.metrics.http_reqs?.values.count || 0,
      };

      await prisma.testHistory.create({
        data: {
          type: "load",
          name: name,
          status: metrics.errorRate < 0.05 ? "passed" : "failed",
          duration: Math.round(summary.metrics.iteration_duration?.values.avg || 0),
          metrics: metrics,
          output: `Load test ${name} completed with ${metrics.totalRequests} requests. Error rate: ${(metrics.errorRate * 100).toFixed(2)}%.`,
          metadata: {
            k6_version: summary.root_group?.name || "unknown",
            baseUrl: baseUrl
          }
        }
      });

      console.log(`Load test ${name} finished and results saved.`);
    }
  } catch (error) {
    console.error(`Load test ${name} failed:`, error);
    try {
        await prisma.testHistory.create({
          data: {
            type: "load",
            name: name,
            status: "error",
            duration: 0,
            output: String(error),
          }
        });
    } catch (dbError) {
        console.error("Failed to save error to DB:", dbError);
    }
  }
}

// Check if k6 is installed
try {
    execSync('k6 version');
    const script = process.argv[2] || "load-tests/webchat-load.js";
    const name = process.argv[3] || "Webchat Load Test";
    runLoadTest(name, script);
} catch (e) {
    console.error("k6 is not installed. Please install k6 to run load tests.");
    // If we are in production, we should probably exit with error if k6 is expected
    const isProduction = process.env.NODE_ENV === "production";
    process.exit(isProduction ? 1 : 0);
}

